function setupAgentWallet(options) {
  const { address, privateKey, isNew } = getOrCreateWallet();
  if (isNew) {
    const notice = formatWalletMigrationNotice(address);
    if (notice) console.error(notice);
    if (!options?.silent) {
      console.error(
        `
BlockRun Agent Wallet Created!
Address: ${address}
Send USDC on Base to get started.
`
      );
    }
  }
  return new LLMClient({ privateKey });
}
async function setupAgentSolanaWallet(options) {
  const result = await getOrCreateSolanaWallet();
  if (result.isNew) {
    const notice = await formatSolanaWalletMigrationNotice(result.address);
    if (notice) console.error(notice);
    if (!options?.silent) {
      console.error(
        `
BlockRun Solana Agent Wallet Created!
Address: ${result.address}
Send USDC on Solana to get started.
`
      );
    }
  }
  return new SolanaLLMClient({ privateKey: result.privateKey });
}
async function status() {
  const client = setupAgentWallet({ silent: true });
  const address = client.getWalletAddress();
  const balance = await client.getBalance();
  console.log(`Wallet: ${address}`);
  console.log(`Balance: $${balance.toFixed(2)} USDC`);
  return { address, balance };
}
async function setupAgentClient(options = {}) {
  if (resolveApiKeyAuth(options)) return new LLMClient({ apiKey: options.apiKey });
  let chain = options.chain;
  if (!chain) {
    for (const file of ["payment-chain", ".chain"]) {
      try {
        const saved = readFileSync7(join7(homedir5(), ".blockrun", file), "utf8").trim();
        if (saved === "solana" || saved === "base") {
          chain = saved;
          break;
        }
      } catch {
      }
    }
  }
  chain ??= !loadSolanaWallet() && loadWallet() ? "base" : "solana";
  return chain === "solana" ? setupAgentSolanaWallet(options) : setupAgentWallet(options);
}

