function writePrivateJsonSync(path: string, value: unknown): void {
  const temporary = `${path}.tmp.${randomUUID()}`;
  try {
    writeFileSync(temporary, JSON.stringify(value, null, 2), { mode: 0o600 });
    renameSync(temporary, path);
    chmodSync(path, 0o600);
  } finally {
    if (existsSync(temporary)) unlinkSync(temporary);
  }
}

function hasConfiguredWallet(): boolean {
  return Boolean(
    process["env"].BLOCKRUN_WALLET_KEY || existsSync(CORE_WALLET_FILE) || existsSync(WALLET_FILE),
  );
}

/**
 * Detect if we're running in shell completion mode.
 * When `openclaw completion --shell zsh` runs, it loads plugins but only needs
 * the completion script output - any stdout logging pollutes the script and
 * causes zsh to interpret colored text like `[plugins]` as glob patterns.
 */
function isCompletionMode(): boolean {
  const args = process.argv;
  // Check for: openclaw completion --shell <shell>
  // argv[0] = node/bun, argv[1] = openclaw, argv[2] = completion
  return args.some((arg, i) => arg === "completion" && i >= 1 && i <= 3);
}

/**
 * Detect if we're running in gateway mode.
 * The proxy should ONLY start when the gateway is running.
 * During CLI commands (plugins, models, etc), the proxy keeps the process alive.
 */
function isGatewayMode(): boolean {
  const args = process.argv;
  // Gateway mode is: openclaw gateway start/restart/stop
  return args.includes("gateway");
}

/**
 * Detect whether BlockRun's web search provider should be disabled.
 *
 * Two opt-out paths:
 * - `BLOCKRUN_WEB_SEARCH=off` env var (case-insensitive) — for CI / one-off runs.
 * - `tools.web.search.enabled === false` in `~/.openclaw/openclaw.json` — persistent,
 *   per-user opt-out. Without a check here, `injectModelsConfig` would re-flip
 *   `enabled` to `true` on every plugin load and `register()` would always wire
 *   blockrun-exa back up.
 *
 * When disabled: `injectModelsConfig` leaves `enabled` untouched and `register()`
 * skips `registerWebSearchProvider`. The on-disk migration that strips the legacy
 * `provider: blockrun-exa` field still runs regardless — that's correctness, not
 * opt-in.
 */
function isBlockrunWebSearchDisabled(config?: unknown): boolean {
  if (process.env.BLOCKRUN_WEB_SEARCH?.toLowerCase() === "off") return true;
  const cfg = (config ?? {}) as { tools?: { web?: { search?: { enabled?: unknown } } } };
  return cfg.tools?.web?.search?.enabled === false;
}

/**
 * Inject BlockRun models config into OpenClaw config file.
 * This is required because registerProvider() alone doesn't make models available.
 *
 * CRITICAL: This function must be idempotent and handle ALL edge cases:
 * - Config file doesn't exist (create it)
 * - Config file exists but is empty/invalid (reinitialize)
 * - blockrun provider exists but has undefined fields (fix them)
 * - Config exists but uses old port/models (update them)
 *
 * This function is called on EVERY plugin load to ensure config is always correct.
 *
 * Also strips any previously managed `mcp.servers.blockrun` entry we wrote in
 * older releases — ClawRouter no longer bundles the MCP bridge (the npx-spawned
 * grandchildren were leaking). The scrub only removes entries matching the
 * managed shape; user-defined `blockrun` MCP servers are left alone.
 */
/**
 * Did a pre-rename @blockrun/clawrouter really occupy the `clawrouter` id?
 *
 * The same on-disk proof `clawrouter setup` uses (src/cli.ts): a legacy package
 * directory whose package.json names @blockrun/clawrouter. Config fields can be
 * absent on a perfectly ordinary BlockRun install; this cannot be produced by
 * OpenClaw's own bundled router, which ships inside OpenClaw and never writes
 * `~/.openclaw/extensions/clawrouter`.
 *
 * Missing, unreadable, or non-BlockRun reads as "not ours" — this only ever
 * grants a migration, so failing closed costs a stale key and never touches
 * someone else's plugin.
 */
function legacyPackageIsBlockRun(): boolean {
  for (const dir of [
    join(homedir(), ".openclaw", "extensions", "clawrouter"),
    join(homedir(), ".openclaw", "npm", "node_modules", "@blockrun", "clawrouter"),
  ]) {
    try {
      const metadata = JSON.parse(readTextFileSync(join(dir, "package.json"))) as {
        name?: unknown;
      };
      if (metadata.name === "@blockrun/clawrouter") return true;
    } catch {
      // Not installed there, or not readable — no evidence, not a refutation.
    }
  }
  return false;
}

function injectModelsConfig(
  logger: { info: (msg: string) => void },
  options: { forceWrite?: boolean; catalogModels?: typeof VISIBLE_OPENCLAW_MODELS } = {},
): void {
  const visibleModels = options.catalogModels ?? VISIBLE_OPENCLAW_MODELS;
  const visibleIds = visibleModels.map((model) => model.id);
  const configDir = join(homedir(), ".openclaw");
  const configPath = join(configDir, "openclaw.json");

  let config: OpenClawConfig = {};
  let needsWrite = false;

  // Create config directory if it doesn't exist
  if (!existsSync(configDir)) {
    try {
      mkdirSync(configDir, { recursive: true });
      logger.info("Created OpenClaw config directory");
    } catch (err) {
      logger.info(
        `Failed to create config dir: ${err instanceof Error ? err.message : String(err)}`,
      );
      return;
    }
  }

  // Load existing config or create new one
  // IMPORTANT: On parse failure, we backup and skip writing to avoid clobbering
  // other plugins' config (e.g. Telegram channels). This prevents a race condition
  // where a partial/corrupt config file causes us to overwrite everything with
  // only our models+agents sections.
  if (existsSync(configPath)) {
    try {
      const content = readTextFileSync(configPath).trim();
      if (content) {
        config = JSON.parse(content);
      } else {
        logger.info("OpenClaw config is empty, initializing");
        needsWrite = true;
      }
    } catch (err) {
      // Config file exists but is corrupt/invalid JSON — likely a partial write
      // from another plugin or a race condition during gateway restart.
      // Backup the corrupt file and SKIP writing to avoid losing other config.
      const backupPath = `${configPath}.backup.${Date.now()}`;
      try {
        copyFileSync(configPath, backupPath);
        logger.info(`Config parse failed, backed up to ${backupPath}`);
      } catch {
        logger.info("Config parse failed, could not create backup");
      }
      logger.info(
        `Skipping config injection (corrupt file): ${err instanceof Error ? err.message : String(err)}`,
      );
      return; // Don't write — we'd lose other plugins' config
    }
  } else {
    logger.info("OpenClaw config not found, creating");
    needsWrite = true;
  }

  // Initialize config structure
  if (!config.models) {
    config.models = {};
    needsWrite = true;
  }
  const models = config.models as Record<string, unknown>;
  if (!models.providers) {
    models.providers = {};
    needsWrite = true;
  }

  const proxyPort = getProxyPort();
  const expectedBaseUrl = `http://127.0.0.1:${proxyPort}/v1`;

  const providers = models.providers as Record<string, unknown>;

  if (!providers.blockrun) {
    // Create new blockrun provider config
    providers.blockrun = {
      baseUrl: expectedBaseUrl,
      api: "openai-completions",
      // apiKey is required by pi-coding-agent's ModelRegistry for providers with models.
      // We use a placeholder since the proxy handles real x402 auth internally.
      apiKey: "x402-proxy-handles-auth",
      models: visibleModels,
    };
    logger.info("Injected BlockRun provider config");
    needsWrite = true;
  } else {
    // Validate and fix existing blockrun config
    const blockrun = providers.blockrun as Record<string, unknown>;
    let fixed = false;

    // Fix: explicitly check for undefined/missing fields
    if (!blockrun.baseUrl || blockrun.baseUrl !== expectedBaseUrl) {
      blockrun.baseUrl = expectedBaseUrl;
      fixed = true;
    }
    // Ensure api field is present
    if (!blockrun.api) {
      blockrun.api = "openai-completions";
      fixed = true;
    }
    // Ensure apiKey is present (required by ModelRegistry for /model picker)
    if (!blockrun.apiKey) {
      blockrun.apiKey = "x402-proxy-handles-auth";
      fixed = true;
    }
    // Refresh models list to the picker-visible subset (TOP_MODELS-filtered).
    // Compare against VISIBLE_OPENCLAW_MODELS so stale or unfiltered arrays
    // (e.g. carryover from pre-v0.12.176 that wrote the full ~175-entry list)
    // get replaced with the trimmed picker set.
    const currentModels = blockrun.models as Array<{ id?: string }>;
    const currentModelIds = new Set<string>(
      Array.isArray(currentModels)
        ? currentModels.map((m) => m?.id).filter((id): id is string => typeof id === "string")
        : [],
    );
    const expectedModelIds = visibleModels.map((m) => m.id);
    const expectedSet = new Set(expectedModelIds);
    const needsModelUpdate =
      JSON.stringify(currentModels) !== JSON.stringify(visibleModels) ||
      !currentModels ||
      !Array.isArray(currentModels) ||
      currentModels.length !== visibleModels.length ||
      expectedModelIds.some((id) => !currentModelIds.has(id)) ||
      Array.from(currentModelIds).some((id) => !expectedSet.has(id));

    if (needsModelUpdate) {
      blockrun.models = visibleModels;
      fixed = true;
      logger.info(`Updated models list (${visibleModels.length} visible models)`);
    }

    if (fixed) {
      logger.info("Fixed incomplete BlockRun provider config");
      needsWrite = true;
    }
  }

  // Set blockrun/auto as default model ONLY on first install (not every load!)
  // This respects user's model selection and prevents hijacking their choice.
  if (!config.agents) {
    config.agents = {};
    needsWrite = true;
  }
  const agents = config.agents as Record<string, unknown>;
  if (!agents.defaults) {
    agents.defaults = {};
    needsWrite = true;
  }
  const defaults = agents.defaults as Record<string, unknown>;
  if (!defaults.model || typeof defaults.model !== "object" || Array.isArray(defaults.model)) {
    // Convert plain string "blockrun/auto" → { primary: "blockrun/auto" }
    // Also handles number, boolean, array, or any other non-object type
    const prev = typeof defaults.model === "string" ? defaults.model : undefined;
    defaults.model = prev ? { primary: prev } : {};
    needsWrite = true;
  }
  const model = defaults.model as Record<string, unknown>;

  // ONLY set default if no primary model exists (first install)
  // Do NOT override user's selection on subsequent loads
  if (!model.primary) {
    model.primary = "blockrun/auto";
    logger.info("Set default model to blockrun/auto (first install)");
    needsWrite = true;
  }

  // Populate agents.defaults.models (the allowlist) with the shared curated
  // BlockRun model list used by install/update scripts too.
  // OpenClaw uses this as a whitelist — only listed models appear in the /model picker.
  // Existing non-blockrun entries are preserved (e.g. from other providers).
  if (!defaults.models || typeof defaults.models !== "object" || Array.isArray(defaults.models)) {
    defaults.models = {};
    needsWrite = true;
  }
  const allowlist = defaults.models as Record<string, unknown>;
  const DEPRECATED_BLOCKRUN_MODELS = ["blockrun/xai/grok-code-fast-1"];
  let removedDeprecatedCount = 0;
  for (const key of DEPRECATED_BLOCKRUN_MODELS) {
    if (allowlist[key]) {
      delete allowlist[key];
      removedDeprecatedCount++;
    }
  }
  if (removedDeprecatedCount > 0) {
    needsWrite = true;
    logger.info(`Removed ${removedDeprecatedCount} deprecated model entries from allowlist`);
  }
  // Sync `blockrun/*` entries to TOP_MODELS exactly: add missing, REMOVE stale.
  // Non-blockrun entries (from other providers like OpenRouter) are preserved.
  // Active prune mirrors what scripts/update.sh / scripts/reinstall.sh do — needed
  // for users on path-based plugin installs where the install scripts never run
  // (otherwise the allowlist accumulates retired models forever).
  const expectedBlockrunKeys = new Set(visibleIds.map((id) => `blockrun/${id}`));
  let addedCount = 0;
  let prunedCount = 0;
  for (const key of Object.keys(allowlist)) {
    if (key.startsWith("blockrun/") && !expectedBlockrunKeys.has(key)) {
      delete allowlist[key];
      prunedCount++;
    }
  }
  for (const id of visibleIds) {
    const key = `blockrun/${id}`;
    if (!allowlist[key]) {
      allowlist[key] = {};
      addedCount++;
    }
  }
  if (addedCount > 0 || prunedCount > 0) {
    needsWrite = true;
    if (prunedCount > 0) {
      logger.info(`Pruned ${prunedCount} stale blockrun/* entries from allowlist`);
    }
    if (addedCount > 0) {
      logger.info(`Added ${addedCount} models to allowlist (${visibleIds.length} total)`);
    }
  }
  // OpenClaw 2026.8+ reads `agents.defaults.modelPolicy.allow` instead of the keys above once
  // it has migrated them, so mirror the same blockrun/* set there (see openclaw-model-policy.ts).
  const policySync = syncBlockrunModelPolicyAllow(defaults, [...expectedBlockrunKeys]);
  if (policySync.added > 0 || policySync.pruned > 0) {
    needsWrite = true;
    logger.info(
      `Synced modelPolicy.allow: +${policySync.added} / -${policySync.pruned} blockrun/* models`,
    );
  }

  // Plugin-id migration (#305) on the gateway-start path.
  //
  // `prepareBlockRunPluginConfig` is otherwise reached only from `clawrouter
  // setup`/`update`/`reinstall` (src/cli.ts). v0.12.265 ran this migration on
  // every gateway start, and dropping that leaves the `npm update -g` + restart
  // path unmigrated — the same way the plugin silently never loaded before that
  // release. Restore it here, where the write is already `isGatewayMode()`-gated
  // below and so cannot trip OpenClaw's install-time baseHash check.
  //
  // Gate it on evidence rather than running unconditionally: that id belongs to
  // OpenClaw's bundled router now, so migrating an entry we did not write would
  // reconfigure an unrelated official plugin.
  //
  // Two kinds of evidence, because config fields alone miss the ordinary case
  // (#319). OpenClaw's installer commits `{ enabled: true }` and nothing else
  // for an enabledByDefault plugin, and the wallet lives at
  // `~/.openclaw/blockrun/wallet.key` rather than in openclaw.json — so a
  // pre-rename BlockRun install usually carries a bare
  // `"clawrouter": { "enabled": true }` with no `walletKey` and no `routing`.
  // Requiring those fields left exactly those users unmigrated on the
  // `npm update -g` + restart path, and the stale key then either enabled a
  // bundled router they never configured or, for a pre-rename opt-out,
  // inverted it: `clawrouter` disabled, `blockrun-clawrouter` enabled by the
  // installer default, and the proxy back up on a machine where it was off.
  //
  // So also accept what `clawrouter setup` already treats as proof: a legacy
  // package directory whose package.json names @blockrun/clawrouter. That is
  // unambiguous in a way config fields are not, and it does not widen the
  // heuristic #313 deliberately narrowed — an entry OpenClaw wrote for its own
  // router has no such directory behind it.
  const legacyEntry = (
    (config.plugins as Record<string, unknown> | undefined)?.entries as
      Record<string, unknown> | undefined
  )?.clawrouter as Record<string, unknown> | undefined;
  const legacyEntryConfig = legacyEntry?.config as Record<string, unknown> | undefined;
  const legacyBlockRunInstall = Boolean(
    legacyEntry &&
    ((["walletKey", "routing"] as const).some(
      (key) => key in legacyEntry || (legacyEntryConfig ? key in legacyEntryConfig : false),
    ) ||
      legacyPackageIsBlockRun()),
  );
  if (legacyBlockRunInstall && prepareBlockRunPluginConfig(config, { legacyBlockRunInstall })) {
    needsWrite = true;
    logger.info(
      `Migrated legacy BlockRun plugin config to ${BLOCKRUN_PLUGIN_ID} (renamed from clawrouter; see #305)`,
    );
  }

  // web_search: set `enabled = true` (safe — boolean, no provider validator),
  // but DELETE any persisted `provider` value. OpenClaw 2026.5.2+ runs a
  // strict known-providers validator on `tools.web.search.provider` at
  // config-load time and during writeConfigFile; persisting `blockrun-exa`
  // (or any plugin-registered provider ID) trips it before register()
  // declares the provider, causing install rollback.
  //
  // With `provider` absent and `enabled = true`, OpenClaw auto-detects the
  // active provider from registered providers — our `registerWebSearchProvider`
  // call in register() makes blockrun-exa the only candidate, so it gets used.
  //
  // Migration: pre-v0.12.186 wrote `blockrun-exa` here. Strip it on next
  // write so users upgrading via install scripts (or `clawrouter setup`)
  // get a clean disk state and the validator stops failing.
  if (!config.tools || typeof config.tools !== "object" || Array.isArray(config.tools)) {
    config.tools = {};
    needsWrite = true;
  }
  const toolsCfg = config.tools as Record<string, unknown>;
  if (!toolsCfg.web || typeof toolsCfg.web !== "object" || Array.isArray(toolsCfg.web)) {
    toolsCfg.web = {};
    needsWrite = true;
  }
  const webCfg = toolsCfg.web as Record<string, unknown>;
  if (!webCfg.search || typeof webCfg.search !== "object" || Array.isArray(webCfg.search)) {
    webCfg.search = {};
    needsWrite = true;
  }
  const searchCfg = webCfg.search as Record<string, unknown>;
  if (searchCfg.provider === BLOCKRUN_EXA_PROVIDER_ID) {
    delete searchCfg.provider;
    needsWrite = true;
    logger.info(
      `Removed legacy tools.web.search.provider=${BLOCKRUN_EXA_PROVIDER_ID} (auto-detected at runtime now)`,
    );
  }
  // Auto-enable search by default, but RESPECT explicit opt-out.
  // If the user (or env BLOCKRUN_WEB_SEARCH=off) has signaled "disabled",
  // leave the field alone — otherwise their opt-out gets clobbered on every
  // plugin load and they'd be stuck with blockrun-exa coming back to life.
  if (!isBlockrunWebSearchDisabled(config) && searchCfg.enabled !== true) {
    searchCfg.enabled = true;
    needsWrite = true;
  }

  if (removeManagedBlockrunMcpServerConfig(config)) {
    needsWrite = true;
    logger.info(
      `Removed bundled BlockRun MCP server config (${BLOCKRUN_MCP_SERVER_NAME}) — restart the gateway to free any leaked processes`,
    );
  }

  // Write config file if any changes were made
  // Use atomic write (temp file + rename) to prevent partial writes that could
  // corrupt the config and cause other plugins to lose their settings on next load.
  //
  // CRITICAL: Skip writes outside gateway mode. OpenClaw's `plugins install`
  // (and other CLI commands that load plugins) loads the config, hashes it as
  // a baseHash, runs plugin activation, then commits its own changes via
  // replaceConfigFile() which calls assertBaseHashMatches(). If we write the
  // file from inside our activation hook, the hash check fails with
  // ConfigMutationConflictError and the entire install rolls back — leaving
  // the user stranded on the previous version. Defer to first gateway start
  // (gateway mode), where no install transaction is in flight; the same hooks
  // re-run there and writes succeed cleanly.
  if (needsWrite) {
    if (!isGatewayMode() && !options.forceWrite) {
      logger.info("Deferring config write to first gateway start (outside gateway mode)");
      return;
    }
    try {
      const tmpPath = `${configPath}.tmp.${process.pid}`;
      writeFileSync(tmpPath, JSON.stringify(config, null, 2), { mode: 0o600 });
      renameSync(tmpPath, configPath);
      chmodSync(configPath, 0o600);
      logger.info("Smart routing enabled (blockrun/auto)");
    } catch (err) {
      logger.info(`Failed to write config: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
}

/**
 * Add the runtime provider entry when the host exposes a mutable config.
 *
 * OpenClaw 2026.10.x freezes the plugin API config during registration. The
 * persisted config has already been handled by injectModelsConfig(), and
 * registerProvider() is the authoritative runtime registration path, so a
 * frozen runtime config must not make plugin registration fail.
 */
function setRuntimeProviderConfig(
  api: Pick<OpenClawPluginApi, "config" | "logger">,
  runtimePort: number,
): void {
  try {
    if (!api.config.models) {
      api.config.models = { providers: {} };
    }
    if (!api.config.models.providers) {
      api.config.models.providers = {};
    }
    api.config.models.providers.blockrun = {
      baseUrl: `http://127.0.0.1:${runtimePort}/v1`,
      api: "openai-completions",
      // apiKey is required by pi-coding-agent's ModelRegistry for providers with models.
      apiKey: "x402-proxy-handles-auth",
      models: VISIBLE_OPENCLAW_MODELS,
    };
  } catch {
    api.logger.debug?.(
      "OpenClaw runtime config is read-only; using the persisted BlockRun provider config",
    );
  }
}

function removeRuntimeMcpConfig(api: Pick<OpenClawPluginApi, "config" | "logger">): boolean {
  try {
    return removeManagedBlockrunMcpServerConfig(api.config);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (
      error instanceof TypeError &&
      /read only|not extensible|Cannot (?:add|assign|delete)/i.test(message)
    ) {
      api.logger.debug?.("OpenClaw runtime MCP config is read-only; skipping managed MCP cleanup");
      return false;
    }
    throw error;
  }
}

/**
 * Repair the per-agent model cache OpenClaw keeps at
 * `~/.openclaw/agents/<agent>/agent/models.json`.
 *
 * This is a THIRD model-list plane, distinct from the two in `openclaw.json`
 * (`models.providers.blockrun.models` = the picker, `agents.defaults.models` =
 * the allowlist). Nothing synced it, so it rotted independently: a machine whose
 * openclaw.json `injectModelsConfig` had just repaired to the current 47 still
 * had 155 entries here — 127 long-retired models (gpt-5.2, gpt-4.1, o1 …) plus
 * duplicate `free` / `moonshot/kimi-k2.5` rows, and none of the current
 * flagships. That is what surfaces as stale and duplicated rows in the picker.
 *
 * Only rewrites when the cache already has a `blockrun` provider — we repair our
 * own entry, never introduce one — and leaves every other provider and each
 * provider's non-`models` fields (baseUrl/api/apiKey) untouched.
 *
 * Gated like `injectModelsConfig`: outside gateway mode this is a no-op unless
 * forced. `openclaw plugins install` runs activation hooks inside a transaction,
 * and writing OpenClaw's own state from under it is what stranded users before
 * (see the baseHash note on the config write above).
 */
function syncAgentModelCache(
  logger: { info: (msg: string) => void },
  options: { forceWrite?: boolean; catalogModels?: typeof VISIBLE_OPENCLAW_MODELS } = {},
): void {
  if (!isGatewayMode() && !options.forceWrite) return;
  const visibleModels = options.catalogModels ?? VISIBLE_OPENCLAW_MODELS;

  const agentsDir = join(homedir(), ".openclaw", "agents");
  if (!existsSync(agentsDir)) return;

  let agentDirs: string[];
  try {
    agentDirs = readdirSync(agentsDir);
  } catch {
    return;
  }

  const expectedIds = visibleModels.map((m) => m.id);

  for (const agent of agentDirs) {
    const cachePath = join(agentsDir, agent, "agent", "models.json");
    if (!existsSync(cachePath)) continue;

    try {
      const raw = readTextFileSync(cachePath).trim();
      if (!raw) continue;
      const cache = JSON.parse(raw) as {
        providers?: Record<string, { models?: Array<{ id?: string }> } | unknown>;
      };
      if (!cache || typeof cache !== "object" || Array.isArray(cache)) continue;

      const blockrun = cache.providers?.blockrun;
      if (!blockrun || typeof blockrun !== "object" || Array.isArray(blockrun)) continue;

      const entry = blockrun as { models?: Array<{ id?: string }> };
      const current = entry.models;
      // Positional compare: order is what the picker renders, so a set-equal but
      // reordered list still needs the rewrite.
      const upToDate =
        Array.isArray(current) &&
        JSON.stringify(current) === JSON.stringify(visibleModels) &&
        current.length === expectedIds.length &&
        current.every((m, i) => m?.id === expectedIds[i]);
      if (upToDate) continue;

      const staleCount = Array.isArray(current) ? current.length : 0;
      entry.models = visibleModels;

      const tmpPath = `${cachePath}.tmp.${process.pid}`;
      writeFileSync(tmpPath, JSON.stringify(cache, null, 2), { mode: 0o600 });
      renameSync(tmpPath, cachePath);
      logger.info(
        `Repaired ${agent} model cache: ${staleCount} → ${expectedIds.length} BlockRun models`,
      );
    } catch (err) {
      // A corrupt or unreadable cache is OpenClaw's to regenerate — never fail setup over it.
      logger.info(
        `Skipped ${agent} model cache: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }
}

/**
 * Inject dummy auth profile for BlockRun into agent auth stores.
 *
 * The legacy ``auth-profiles.json`` write is now deliberately narrow:
 *
 * - Wherever ``openclaw-agent.sqlite`` exists, the SQLite auth store is
 *   authoritative. Writing the legacy JSON beside it is at best ignored, at
 *   worst a failed-closed migration trigger: since OpenClaw 2026.8.1 a
 *   leftover legacy file beside a store that holds no profiles fails auth
 *   migration for the whole agent fleet. So we never write there, and we
 *   clean up the placeholder we previously injected.
 * - The shared auth-owner directory (``main``) is managed by OpenClaw
 *   itself; a placeholder written there can shadow that state. The
 *   provider's real auth comes from the x402 proxy (and the apiKey
 *   injectModelsConfig writes into openclaw.json), so nothing is lost.
 * - Only on very old installs with no SQLite store at all do we keep the
 *   original JSON bootstrap, which those releases import.
 */
function injectAuthProfile(logger: { info: (msg: string) => void }): void {
  const agentsDir = join(homedir(), ".openclaw", "agents");

  // Create agents directory if it doesn't exist
  if (!existsSync(agentsDir)) {
    try {
      mkdirSync(agentsDir, { recursive: true });
    } catch (err) {
      logger.info(
        `Could not create agents dir: ${err instanceof Error ? err.message : String(err)}`,
      );
      return;
    }
  }

  try {
    // Find all agent directories
    let agents = readdirSync(agentsDir, { withFileTypes: true })
      .filter((d) => d.isDirectory())
      .map((d) => d.name);

    // Always ensure "main" agent has auth (most common agent)
    if (!agents.includes("main")) {
      agents = ["main", ...agents];
    }

    for (const agentId of agents) {
      const authDir = join(agentsDir, agentId, "agent");
      const authPath = join(authDir, "auth-profiles.json");
      const sqlitePath = join(authDir, "openclaw-agent.sqlite");

      // SQLite store exists: it is authoritative, and the legacy JSON is
      // obsolete. Remove our own placeholder and never rewrite it.
      if (existsSync(sqlitePath)) {
        removeInjectedAuthPlaceholder(authPath, logger, agentId);
        continue;
      }

      // Never write into the shared auth-owner directory. OpenClaw manages
      // its credentials centrally, and a leftover legacy file there is what
      // fails dispatch closed on 2026.8.1+ when that store is empty.
      if (agentId === "main") {
        removeInjectedAuthPlaceholder(authPath, logger, agentId);
        continue;
      }

      // Create agent dir if needed
      if (!existsSync(authDir)) {
        try {
          mkdirSync(authDir, { recursive: true });
        } catch {
          continue; // Skip if we can't create the dir
        }
      }

      // Load or create auth-profiles.json with correct OpenClaw format
      // Format: { version: 1, profiles: { "provider:profileId": { type, provider, key } } }
      let store: { version: number; profiles: Record<string, unknown> } = {
        version: 1,
        profiles: {},
      };
      if (existsSync(authPath)) {
        try {
          const existing = JSON.parse(readTextFileSync(authPath));
          // Check if valid OpenClaw format (has version and profiles)
          if (existing.version && existing.profiles) {
            store = existing;
          }
          // Old format without version/profiles is discarded and recreated
        } catch {
          // Invalid JSON, use fresh store
        }
      }

      // Check if blockrun auth already exists (OpenClaw format: profiles["provider:profileId"])
      const profileKey = "blockrun:default";
      if (store.profiles[profileKey]) {
        continue; // Already configured
      }

      // Inject placeholder auth for blockrun (OpenClaw format)
      // The proxy handles real x402 auth internally, this just satisfies OpenClaw's lookup
      store.profiles[profileKey] = {
        type: "api_key",
        provider: "blockrun",
        key: "x402-proxy-handles-auth",
      };

      try {
        writePrivateJsonSync(authPath, store);
        logger.info(`Injected BlockRun auth profile for agent: ${agentId}`);
      } catch (err) {
        logger.info(
          `Could not inject auth for ${agentId}: ${err instanceof Error ? err.message : String(err)}`,
        );
      }
    }
  } catch (err) {
    logger.info(`Auth injection failed: ${err instanceof Error ? err.message : String(err)}`);
  }
}

/**
 * Remove a legacy ``auth-profiles.json`` — but only when it contains nothing
 * but the exact placeholder this plugin injects. A real user credential file
 * is never touched.
 */
function removeInjectedAuthPlaceholder(
  authPath: string,
  logger: { info: (msg: string) => void },
  agentId: string,
): void {
  try {
    if (!existsSync(authPath)) return;
    const parsed = JSON.parse(readTextFileSync(authPath)) as {
      profiles?: Record<string, unknown>;
    };
    const profiles = parsed?.profiles;
    if (!profiles || typeof profiles !== "object" || Array.isArray(profiles)) return;
    const keys = Object.keys(profiles);
    if (keys.length !== 1 || keys[0] !== "blockrun:default") return;
    const entry = profiles["blockrun:default"];
    if (!entry || typeof entry !== "object") return;
    const profile = entry as { type?: unknown; provider?: unknown; key?: unknown };
    if (
      profile.type !== "api_key" ||
      profile.provider !== "blockrun" ||
      profile.key !== "x402-proxy-handles-auth"
    ) {
      return;
    }
    unlinkSync(authPath);
    logger.info(`Removed legacy BlockRun auth placeholder for agent: ${agentId}`);
  } catch {
    // Unreadable or not our file — leave it alone.
  }
}

// Store active proxy handle for cleanup on gateway_stop
let activeProxyHandle: Awaited<ReturnType<typeof startProxy>> | null = null;
let pendingConfiguredStartupApi: OpenClawPluginApi | null = null;
type ProcessWithClawRouterState = NodeJS.Process & {
  __clawrouterProxyStarted?: boolean;
  __clawrouterDeferredStartTimer?: ReturnType<typeof setTimeout>;
  __clawrouterStartupGeneration?: number;
  __clawrouterStartedWithEmptyConfig?: boolean;
  __clawrouterStartupPhase?: "idle" | "probing" | "starting" | "running";
  /** Suppress verbose registration logs on repeat register() calls. */
  __clawrouterRegistrationLogged?: boolean;
};

function clearDeferredProxyStartTimer(
  proc: ProcessWithClawRouterState = process as ProcessWithClawRouterState,
): boolean {
  if (!proc.__clawrouterDeferredStartTimer) return false;
  clearTimeout(proc.__clawrouterDeferredStartTimer);
  proc.__clawrouterDeferredStartTimer = undefined;
  return true;
}

function beginProxyStartupAttempt(
  proc: ProcessWithClawRouterState = process as ProcessWithClawRouterState,
  startedWithEmptyConfig = false,
): number {
  const generation = (proc.__clawrouterStartupGeneration ?? 0) + 1;
  proc.__clawrouterStartupGeneration = generation;
  proc.__clawrouterProxyStarted = true;
  proc.__clawrouterStartedWithEmptyConfig = startedWithEmptyConfig;
  proc.__clawrouterStartupPhase = "probing";
  return generation;
}

function isProxyStartupCurrent(
  generation: number,
  proc: ProcessWithClawRouterState = process as ProcessWithClawRouterState,
): boolean {
  return (
    proc.__clawrouterStartupGeneration === generation && proc.__clawrouterProxyStarted === true
  );
}

function resetProxyStartupState(): void {
  const proc = process as ProcessWithClawRouterState;
  clearDeferredProxyStartTimer(proc);
  pendingConfiguredStartupApi = null;
  proc.__clawrouterStartupGeneration = (proc.__clawrouterStartupGeneration ?? 0) + 1;
  proc.__clawrouterProxyStarted = false;
  proc.__clawrouterStartedWithEmptyConfig = false;
  proc.__clawrouterStartupPhase = "idle";
  setActiveProxy(null);
}

function startPendingConfiguredProxyIfQueued(
  proc: ProcessWithClawRouterState = process as ProcessWithClawRouterState,
): boolean {
  if (!pendingConfiguredStartupApi) return false;
  if (proc.__clawrouterProxyStarted || activeProxyHandle) {
    pendingConfiguredStartupApi = null;
    return false;
  }
  const api = pendingConfiguredStartupApi;
  pendingConfiguredStartupApi = null;
  const generation = beginProxyStartupAttempt(proc, false);
  api.logger.info("Starting proxy with populated pluginConfig");
  startProxyAfterPortProbe(api, generation);
  return true;
}

function resumePendingConfiguredProxyAfterStaleFailure(
  proc: ProcessWithClawRouterState = process as ProcessWithClawRouterState,
): boolean {
  if (!pendingConfiguredStartupApi) return false;
  if (proc.__clawrouterProxyStarted || activeProxyHandle) return false;
  proc.__clawrouterStartupPhase = "idle";
  return startPendingConfiguredProxyIfQueued(proc);
}

function supersedeEmptyConfigStartup(api: OpenClawPluginApi): void {
  const proc = process as ProcessWithClawRouterState;
  pendingConfiguredStartupApi = api;
  proc.__clawrouterStartupGeneration = (proc.__clawrouterStartupGeneration ?? 0) + 1;
  proc.__clawrouterProxyStarted = false;
  proc.__clawrouterStartedWithEmptyConfig = false;

  if (activeProxyHandle) {
    const oldHandle = activeProxyHandle;
    activeProxyHandle = null;
    setActiveProxy(null);
    proc.__clawrouterStartupPhase = "idle";
    void oldHandle
      .close()
      .catch(() => {})
      .finally(() => {
        startPendingConfiguredProxyIfQueued(proc);
      });
    return;
  }

  if (proc.__clawrouterStartupPhase === "starting") {
    api.logger.info(
      "Populated pluginConfig arrived during provisional startup — queued restart with current config",
    );
    return;
  }

  proc.__clawrouterStartupPhase = "idle";
  startPendingConfiguredProxyIfQueued(proc);
}

/**
 * Start the x402 proxy in the background.
 * Called from register() because OpenClaw's loader only invokes register(),
 * treating activate() as an alias (def.register ?? def.activate).
 */
async function startProxyInBackground(
  api: OpenClawPluginApi,
  startupGeneration?: number,
): Promise<boolean> {
  const proc = process as ProcessWithClawRouterState;
  if (startupGeneration !== undefined && isProxyStartupCurrent(startupGeneration, proc)) {
    proc.__clawrouterStartupPhase = "starting";
  }

  // An API key, if the user has one, is resolved before any wallet is touched.
  // resolveOrGenerateWalletKey() below *generates* a wallet as a side effect,
  // and a customer paying by card must not end up with a private key they never
  // asked for and a "back this up" warning they cannot act on.
  const pluginApiKey = api.pluginConfig?.apiKey as string | undefined;
  // A configured-but-invalid key is refused rather than ignored, for the same
  // reason resolveApiKey() refuses one: "look elsewhere" ends at a different
  // account or at resolveOrGenerateWalletKey(), which mints a wallet and spends
  // USDC the user meant to bill to their account. An empty value is "unset",
  // not "invalid" — clearing a config field is a normal way to turn it off.
  if (typeof pluginApiKey === "string" && pluginApiKey.trim() && !isValidApiKey(pluginApiKey)) {
    throw new Error(
      `pluginConfig.apiKey is set but is not a BlockRun key (expected brk_…). ` +
        `Fix it or remove it — refusing to fall back to another credential.`,
    );
  }
  const resolvedApiKey =
    typeof pluginApiKey === "string" && isValidApiKey(pluginApiKey)
      ? { key: pluginApiKey.trim(), source: "config" as const }
      : await resolveApiKey();
  const apiKey = resolvedApiKey?.key;

  // Resolve wallet key: plugin config → explicit env → BlockRun Core → legacy migration → generate.
  // pluginConfig.walletKey is declared in openclaw.plugin.json configSchema but
  // was previously never read here — that was a bug.
  const configKey = api.pluginConfig?.walletKey as string | undefined;
  let wallet: WalletResolution | undefined;

  if (apiKey) {
    api.logger.info(
      `Using BlockRun API key ${maskApiKey(apiKey)} (from ${resolvedApiKey!.source}) — billing account credit, no wallet`,
    );
  } else if (typeof configKey === "string" && /^0x[0-9a-fA-F]{64}$/.test(configKey)) {
    const account = privateKeyToAccount(configKey as `0x${string}`);
    wallet = { key: configKey, address: account.address, source: "config" };
  } else {
    if (configKey !== undefined) {
      api.logger.warn(
        `pluginConfig.walletKey is set but invalid (expected 0x + 64 hex chars) — falling back to the BlockRun wallet`,
      );
    }
    wallet = await resolveOrGenerateWalletKey();
  }

  // Log wallet source
  if (!wallet) {
    // API-key mode — nothing to report, the line above already said so.
  } else if (wallet.source === "generated") {
    api.logger.warn(`════════════════════════════════════════════════`);
    api.logger.warn(`  NEW WALLET GENERATED — BACK UP YOUR KEY NOW!`);
    api.logger.warn(`  Address : ${wallet.address}`);
    api.logger.warn(`  Run /wallet export to get your private key`);
    api.logger.warn(`  Losing this key = losing your USDC funds`);
    api.logger.warn(`════════════════════════════════════════════════`);
  } else if (wallet.source === "core") {
    api.logger.info(`Using BlockRun Core wallet: ${wallet.address}`);
  } else if (wallet.source === "saved") {
    api.logger.info(`Using saved wallet: ${wallet.address}`);
  } else if (wallet.source === "config") {
    api.logger.info(`Using wallet from plugin config: ${wallet.address}`);
  } else {
    api.logger.info(`Using wallet from BLOCKRUN_WALLET_KEY: ${wallet.address}`);
  }

  // Resolve routing config overrides from plugin config
  const routingConfig = api.pluginConfig?.routing as Partial<RoutingConfig> | undefined;

  const maxCostPerRunUsd =
    typeof api.pluginConfig?.maxCostPerRun === "number" &&
    Number.isFinite(api.pluginConfig.maxCostPerRun)
      ? (api.pluginConfig.maxCostPerRun as number)
      : undefined;

  const maxCostPerRunMode: "graceful" | "strict" =
    api.pluginConfig?.maxCostPerRunMode === "strict" ? "strict" : "graceful";

  if (maxCostPerRunUsd !== undefined) {
    api.logger.info(
      `Cost cap: $${maxCostPerRunUsd.toFixed(2)} per session (mode: ${maxCostPerRunMode})`,
    );
  }

  // Restart semantics for the process-wide ledger. The rolling hourly/daily
  // windows and the history behind them survive an in-process proxy restart —
  // that is the point of a shared ledger. Two things must NOT survive it:
  //   - limits, which are re-read so a hand-edit to spending.json made while
  //     the proxy was up still applies
  //   - the session window, which docs/configuration.md and the /policy help
  //     both define as resetting on restart. It used to reset by accident
  //     (every startProxy built its own SpendControl); with one ledger for the
  //     whole process it has to be reset on purpose, or `session` quietly
  //     becomes "since the gateway booted".
  const sharedControl = getSharedSpendControl();
  sharedControl.reloadLimits();
  sharedControl.resetSession();
  const proxy = await startProxy({
    ...(apiKey ? { apiKey } : { wallet: wallet! }),
    routingConfig,
    maxCostPerRunUsd,
    maxCostPerRunMode,
    // The process-wide ledger: the polymarket tool and the /policy command
    // registered below use the same instance, so hourly/daily/session windows
    // cover every surface and a /policy write reaches the live signer.
    spendControl: sharedControl,
    onCatalogUpdated: (catalogModels) => {
      if (startupGeneration !== undefined && !isProxyStartupCurrent(startupGeneration)) return;
      injectModelsConfig(api.logger, { catalogModels });
      syncAgentModelCache(api.logger, { catalogModels });
    },
    onReady: (port) => {
      api.logger.info(`BlockRun ${apiKey ? "API-key" : "x402"} proxy listening on port ${port}`);
    },
    onError: (error) => {
      api.logger.error(`BlockRun proxy error: ${error.message}`);
    },
    onRouted: (decision) => {
      const cost = decision.costEstimate.toFixed(4);
      const saved = (decision.savings * 100).toFixed(0);
      api.logger.info(
        `[${decision.tier}] ${decision.model} $${cost} (saved ${saved}%) | ${decision.reasoning}`,
      );
    },
    onShadowRouted: (comparison) => {
      api.logger.info(
        `[router-shadow] executed=${comparison.executed.model} (${comparison.executed.method}) ` +
          `candidate=${comparison.shadow.model} (${comparison.shadow.method}) ` +
          `same=${comparison.sameModel} tools=${comparison.hasTools} ` +
          `vision=${comparison.hasVision} structured=${comparison.requiresStructuredOutput}`,
      );
    },
    onLowBalance: (info) => {
      api.logger.warn(`[!] Low balance: ${info.balanceUSD}. Fund wallet: ${info.walletAddress}`);
    },
    onInsufficientFunds: (info) => {
      api.logger.error(
        `[!] Insufficient funds. Balance: ${info.balanceUSD}, Needed: ${info.requiredUSD}. Fund wallet: ${info.walletAddress}`,
      );
    },
  });

  if (startupGeneration !== undefined && !isProxyStartupCurrent(startupGeneration)) {
    try {
      await proxy.close();
    } catch {
      // Best-effort cleanup for stale startup attempts
    }
    proc.__clawrouterStartupPhase = "idle";
    startPendingConfiguredProxyIfQueued(proc);
    return false;
  }

  setActiveProxy(proxy);
  activeProxyHandle = proxy;
  proc.__clawrouterStartupPhase = "running";

  const startupExclusions = loadExcludeList();
  if (startupExclusions.size > 0) {
    api.logger.info(
      `Model exclusions active (${startupExclusions.size}): ${[...startupExclusions].join(", ")}`,
    );
  }

  api.logger.info(`ClawRouter ready — smart routing enabled`);
  api.logger.info(`Pricing: Simple ~$0.001 | Code ~$0.01 | Complex ~$0.05 | Free: $0`);

  // API-key mode has no wallet balance to check and no address to fund: the
  // gateway holds the books and refuses with a 402 that names the top-up page.
  if (apiKey) {
    api.logger.info(`Billing: BlockRun account credit — top up at ${PORTAL_CREDITS_URL}`);
    return true;
  }

  // Non-blocking balance check AFTER proxy is ready (won't hang startup)
  // Uses the proxy's chain-aware balance monitor and matching active-chain address.
  const currentChain = await resolvePaymentChain();
  const displayAddress =
    currentChain === "solana" && proxy.solanaAddress ? proxy.solanaAddress : wallet!.address;
  const network = PAYMENT_CHAIN_LABELS[currentChain];
  proxy.balanceMonitor
    .checkBalance()
    .then(async (balance) => {
      if (balance.isEmpty) {
        api.logger.info(`Wallet (${network}): ${displayAddress}`);
        api.logger.info(
          `Balance: $0.00 — send USDC on ${network} to the address above to unlock paid models.`,
        );
      } else if (balance.isLow) {
        api.logger.info(
          `Wallet (${network}): ${displayAddress} | Balance: ${balance.balanceUSD} (low — top up soon)`,
        );
      } else {
        api.logger.info(`Wallet (${network}): ${displayAddress} | Balance: ${balance.balanceUSD}`);
      }
      // On Solana, if USDC is low/empty, check for SOL and suggest swap
      if (currentChain === "solana" && (balance.isEmpty || balance.isLow)) {
        try {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const solLamports: bigint = await (proxy.balanceMonitor as any).checkSolBalance();
          // Only suggest if they have meaningful SOL (> 0.01 SOL = 10M lamports)
          if (solLamports > 10_000_000n) {
            const sol = Number(solLamports) / 1_000_000_000;
            api.logger.info(
              `You have ${sol.toFixed(2)} SOL — swap to USDC: https://jup.ag/swap/SOL-USDC`,
            );
          }
        } catch {
          // SOL check is best-effort, don't block startup
        }
      }
    })
    .catch(() => {
      api.logger.info(`Wallet (${network}): ${displayAddress} | Balance: (checking...)`);
    });
  return true;
}

/**
 * Probe the proxy port and start the proxy in the background if free.
 * Extracted so the deferred-startup timer (#147 fix) can call it too.
 */
function startProxyAfterPortProbe(api: OpenClawPluginApi, startupGeneration: number): void {
  const proxyPort = getProxyPort();
  const portProbe = import("node:net").then(
    (net) =>
      new Promise<boolean>((resolve) => {
        const sock = net.connect({ host: "127.0.0.1", port: proxyPort }, () => {
          sock.destroy();
          resolve(true); // port is already in use
        });
        sock.on("error", () => resolve(false)); // port is free
        sock.setTimeout(500, () => {
          sock.destroy();
          resolve(false);
        });
      }),
  );
  portProbe
    .then((portInUse) => {
      if (!isProxyStartupCurrent(startupGeneration)) {
        return;
      }
      if (portInUse) {
        resetProxyStartupState();
        api.logger.info(
          `Port ${proxyPort} already in use — skipping proxy startup (another instance running)`,
        );
        return;
      }
      return startProxyInBackground(api, startupGeneration).then(async (started) => {
        if (!started || !isProxyStartupCurrent(startupGeneration)) {
          return;
        }
        const port = getProxyPort();
        const healthy = await waitForProxyHealth(port, 15000);
        if (!healthy && isProxyStartupCurrent(startupGeneration)) {
          api.logger.warn(`Proxy health check timed out, commands may not work immediately`);
        }
      });
    })
    .catch((err) => {
      if (isProxyStartupCurrent(startupGeneration)) {
        resetProxyStartupState();
      } else {
        resumePendingConfiguredProxyAfterStaleFailure();
      }
      api.logger.error(
        `Failed to start BlockRun proxy: ${err instanceof Error ? err.message : String(err)}`,
      );
    });
}

