/**
 * /wallet command handler for ClawRouter.
 * - /wallet or /wallet status: Show wallet address, balance, usage, and key file location
 * - /wallet export: Show private key for backup (with security warning)
 */

// Local directories where the proxy saves media files
const IMAGE_DIR = join(homedir(), ".openclaw", "blockrun", "images");
const AUDIO_DIR = join(homedir(), ".openclaw", "blockrun", "audio");

/**
 * Parse a `/cr-call` args string.
 *
 * Shape: `/cr-call +14155552671 "Tell them X" [--voice nat] [--max-duration 5] [--from +1...] [--language en-US]`
 *
 * - First token starting with `+` is `to` (E.164 destination).
 * - All remaining non-flag tokens are joined into `task` (the prompt for the AI agent).
 *   Quoted spans stay intact.
 * - Flags accept both `--key value` (space-separated) and `--key=value` forms.
 */
export function parseCallArgs(raw: string): {
  to?: string;
  task: string;
  voice?: string;
  max_duration?: number;
  from?: string;
  language?: string;
} {
  let to: string | undefined;
  let voice: string | undefined;
  let from: string | undefined;
  let language: string | undefined;
  let max_duration: number | undefined;
  const taskParts: string[] = [];
  // Tokenize: keep "quoted spans" together as a single token (sans quotes).
  const tokens = raw.trim().match(/"[^"]*"|\S+/g) ?? [];
  for (let i = 0; i < tokens.length; i++) {
    const raw = tokens[i];
    const tok = raw.startsWith('"') && raw.endsWith('"') ? raw.slice(1, -1) : raw;
    // --key=value form
    const eqMatch = tok.match(/^--(voice|max-duration|max_duration|from|language|lang)=(.+)$/);
    if (eqMatch) {
      const [, key, value] = eqMatch;
      if (key === "voice") voice = value;
      else if (key === "max-duration" || key === "max_duration") max_duration = Number(value);
      else if (key === "from") from = value;
      else if (key === "language" || key === "lang") language = value;
      continue;
    }
    // --key value form
    const spaceMatch = tok.match(/^--(voice|max-duration|max_duration|from|language|lang)$/);
    if (spaceMatch) {
      const next = tokens[i + 1];
      if (next !== undefined) {
        const value = next.startsWith('"') && next.endsWith('"') ? next.slice(1, -1) : next;
        const key = spaceMatch[1];
        if (key === "voice") voice = value;
        else if (key === "max-duration" || key === "max_duration") max_duration = Number(value);
        else if (key === "from") from = value;
        else if (key === "language" || key === "lang") language = value;
        i++;
      }
      continue;
    }
    // First +E.164-shaped token wins as `to`
    if (!to && /^\+\d{6,15}$/.test(tok)) {
      to = tok;
      continue;
    }
    taskParts.push(tok);
  }
  return {
    to,
    task: taskParts.join(" ").trim(),
    voice,
    from,
    language,
    ...(Number.isFinite(max_duration) ? { max_duration } : {}),
  };
}

/**
 * Parse a `/cr-imagegen` or `/videogen` args string.
 * Supports `--model=<alias>`, `--size=<WxH>`, `--n=<int>`, `--duration=<int>`.
 * Everything else — in order — is joined into the prompt.
 */
function parseGenArgs(raw: string): {
  prompt: string;
  model?: string;
  size?: string;
  n?: number;
  duration?: number;
} {
  const promptParts: string[] = [];
  let model: string | undefined;
  let size: string | undefined;
  let n: number | undefined;
  let duration: number | undefined;
  // Split on whitespace but keep --flag=value together (no shell-style quoting).
  const tokens = raw.trim().match(/(?:[^\s"]+|"[^"]*")+/g) ?? [];
  for (const tok of tokens) {
    const t = tok.startsWith('"') && tok.endsWith('"') ? tok.slice(1, -1) : tok;
    const flagMatch = t.match(/^--(model|size|n|count|duration|duration_seconds)=(.+)$/);
    if (flagMatch) {
      const [, key, value] = flagMatch;
      if (key === "model") model = value;
      else if (key === "size") size = value;
      else if (key === "n" || key === "count") n = Number(value);
      else if (key === "duration" || key === "duration_seconds") duration = Number(value);
      continue;
    }
    promptParts.push(t);
  }
  return {
    prompt: promptParts.join(" ").trim(),
    model,
    size,
    ...(Number.isFinite(n) ? { n } : {}),
    ...(Number.isFinite(duration) ? { duration } : {}),
  };
}

/**
 * Build the ImageGenerationProvider that registers BlockRun image models
 * with OpenClaw's native image generation UI.
 * Delegates to the local proxy (which handles x402 payment).
 */
export function buildImageGenerationProvider(): ImageGenerationProviderPlugin {
  return {
    id: "blockrun",
    label: "BlockRun",
    defaultModel: "google/nano-banana",
    // Must stay in sync with IMAGE_PRICING (proxy.ts). OpenClaw sends the
    // picked id straight to /v1/images/generations, which forwards the body
    // verbatim with no alias resolution, so a retired id here is a guaranteed
    // upstream 400. dall-e-3 (delisted 2026-05-25) and flux-1.1-pro (no
    // gateway entry) were dropped in v0.12.227 and had lingered here.
    // Kept as a hand-written array (not spread from IMAGE_MODEL_IDS) because
    // this is the picker's curated display order — default model first, which
    // IMAGE_PRICING declaration order does not give — and because the
    // lifecycle tests fully mock ./proxy.js. Set-equality is enforced by
    // src/index.image-provider.test.ts, which pins the two lists together.
    models: [
      "google/nano-banana",
      "google/nano-banana-2",
      "google/nano-banana-2-lite",
      "google/nano-banana-2.1",
      "google/nano-banana-pro",
      "openai/gpt-image-1",
      "openai/gpt-image-2",
      "openai/gpt-image-2.5-flare",
      "openai/gpt-image-2.5-sunburst",
      "bytedance/seedream-5-pro",
      "xai/grok-imagine-image",
      "xai/grok-imagine-image-2.0",
      "xai/grok-imagine-image-pro",
      "zai/cogview-4",
    ],
    capabilities: {
      generate: {
        maxCount: 1,
        supportsSize: true,
        supportsAspectRatio: false,
        supportsResolution: false,
      },
      // Edit is served for gpt-image-1, gpt-image-2, gpt-image-2.5-sunburst and
      // the five nano-banana models (blockrun EDIT_SUPPORTED_MODELS; Flare is
      // rejected); OpenClaw's UI picks a compatible model at edit time via
      // /v1/images/image2image.
      edit: { enabled: true },
      // Union of every size the gateway accepts across the models above,
      // live-probed 2026-08-23 (the gateway validates size per-model BEFORE
      // payment and 400s unknown ones — 1216x832 / 1792x1024 / 1024x1792 were
      // accepted by no model and are gone with dall-e-3). Pinned against
      // IMAGE_MODEL_SIZES (proxy.ts) by src/index.image-provider.test.ts.
      geometry: {
        sizes: [
          "512x512",
          "768x768",
          "768x1344",
          "1024x1024",
          "1024x1536",
          "1280x720",
          "1344x768",
          "1440x1440",
          "1536x1024",
          "1600x2848",
          "1728x2304",
          "2048x1024",
          "2048x2048",
          "2304x1728",
          "2848x1600",
          "4096x4096",
        ],
      },
    },
    isConfigured: hasConfiguredWallet,
    generateImage: async (req: ImageGenerationRequest) => {
      const port = getProxyPort();
      const body = JSON.stringify({
        model: req.model,
        prompt: req.prompt,
        size: req.size ?? "1024x1024",
        n: req.count ?? 1,
      });
      const resp = await fetch(`http://127.0.0.1:${port}/v1/images/generations`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body,
        signal: req.timeoutMs ? AbortSignal.timeout(req.timeoutMs) : undefined,
      });
      if (!resp.ok) {
        const errText = await resp.text().catch(() => "");
        throw new Error(`BlockRun image generation failed (${resp.status}): ${errText}`);
      }
      const result = (await resp.json()) as {
        data?: Array<{ url?: string; revised_prompt?: string }>;
        model?: string;
      };
      const images = await Promise.all(
        (result.data ?? []).map(async (img) => {
          // URL format: http://localhost:PORT/images/FILENAME
          const filename = img.url?.split("/images/").pop();
          if (!filename) throw new Error(`Unexpected image URL format: ${img.url}`);
          const filePath = join(IMAGE_DIR, filename);
          const buffer = await readFileAsync(filePath);
          const ext = filename.split(".").pop()?.toLowerCase() ?? "png";
          const mimeType =
            ext === "jpg" || ext === "jpeg"
              ? "image/jpeg"
              : ext === "webp"
                ? "image/webp"
                : "image/png";
          return { buffer, mimeType, fileName: filename, revisedPrompt: img.revised_prompt };
        }),
      );
      return { images, model: result.model ?? req.model };
    },
  };
}

/**
 * Build the MusicGenerationProvider that registers BlockRun music models
 * with OpenClaw's native music generation UI.
 * Delegates to the local proxy (which handles x402 payment).
 */
function buildMusicGenerationProvider(): MusicGenerationProviderPlugin {
  return {
    id: "blockrun",
    label: "BlockRun",
    defaultModel: "minimax/music-2.5+",
    // minimax/music-2.5 left blockrun's catalog; the gateway remaps pinned
    // callers to music-2.5+, so the picker offers only the model that is served.
    models: ["minimax/music-2.5+"],
    capabilities: {
      maxTracks: 1,
      maxDurationSeconds: 240,
      supportsLyrics: true,
      supportsInstrumental: true,
      supportsDuration: true,
      supportsFormat: true,
      supportedFormats: ["mp3"],
    },
    isConfigured: hasConfiguredWallet,
    generateMusic: async (req: MusicGenerationRequest) => {
      const port = getProxyPort();
      const body = JSON.stringify({
        model: req.model,
        prompt: req.prompt,
        ...(req.lyrics ? { lyrics: req.lyrics } : {}),
        ...(req.instrumental !== undefined ? { instrumental: req.instrumental } : {}),
        ...(req.durationSeconds ? { duration_seconds: req.durationSeconds } : {}),
      });
      // Music generation can take up to 3 minutes
      const timeoutMs = req.timeoutMs ?? 200_000;
      const resp = await fetch(`http://127.0.0.1:${port}/v1/audio/generations`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body,
        signal: AbortSignal.timeout(timeoutMs),
      });
      if (!resp.ok) {
        const errText = await resp.text().catch(() => "");
        throw new Error(`BlockRun music generation failed (${resp.status}): ${errText}`);
      }
      const result = (await resp.json()) as {
        data?: Array<{ url?: string; duration_seconds?: number; lyrics?: string }>;
        model?: string;
      };
      const tracks = await Promise.all(
        (result.data ?? []).map(async (track) => {
          // URL format: http://localhost:PORT/audio/FILENAME
          const filename = track.url?.split("/audio/").pop();
          if (!filename) throw new Error(`Unexpected audio URL format: ${track.url}`);
          const filePath = join(AUDIO_DIR, filename);
          const buffer = await readFileAsync(filePath);
          const ext = filename.split(".").pop()?.toLowerCase() ?? "mp3";
          const mimeType = ext === "wav" ? "audio/wav" : "audio/mpeg";
          return {
            buffer,
            mimeType,
            fileName: filename,
            metadata: {
              ...(track.duration_seconds ? { duration_seconds: track.duration_seconds } : {}),
              ...(track.lyrics ? { lyrics: track.lyrics } : {}),
            },
          };
        }),
      );
      const allLyrics = (result.data ?? [])
        .map((t) => t.lyrics)
        .filter((l): l is string => Boolean(l));
      return {
        tracks,
        model: result.model ?? req.model,
        lyrics: allLyrics.length ? allLyrics : undefined,
      };
    },
  };
}

const VIDEO_DIR = join(homedir(), ".openclaw", "blockrun", "videos");

/**
 * Build the VideoGenerationProvider that registers BlockRun video models
 * with OpenClaw's native video generation UI.
 * Delegates to the local proxy (which handles x402 payment + polling).
 */
function buildVideoGenerationProvider(): VideoGenerationProviderPlugin {
  return {
    id: "blockrun",
    label: "BlockRun",
    defaultModel: "xai/grok-imagine-video",
    models: [
      "xai/grok-imagine-video",
      // Grok Imagine Video 1.5 (blockrun live catalog): native synced audio,
      // 1–15s, $0.08/s at the 480p default — so 5/8/10s all fit.
      "xai/grok-imagine-video-1.5",
      "bytedance/seedance-1.5-pro",
      "bytedance/seedance-2.0-fast",
      "bytedance/seedance-2.0",
      "bytedance/seedance-2.0-mini",
      "bytedance/seedance-2.5",
    ],
    capabilities: {
      maxVideos: 1,
      maxInputImages: 1,
      maxDurationSeconds: 10,
      supportedDurationSeconds: [5, 8, 10],
      supportsAudio: false,
      imageToVideo: {
        enabled: true,
        maxInputImages: 1,
        maxDurationSeconds: 10,
        supportedDurationSeconds: [5, 8, 10],
      },
    },
    isConfigured: hasConfiguredWallet,
    generateVideo: async (req: VideoGenerationRequest) => {
      const port = getProxyPort();
      const imageUrl = req.inputImages?.[0]?.url;
      const body = JSON.stringify({
        model: req.model,
        prompt: req.prompt,
        ...(imageUrl ? { image_url: imageUrl } : {}),
        ...(req.durationSeconds ? { duration_seconds: req.durationSeconds } : {}),
      });
      // Video generation: ClawRouter proxy internally polls upstream for up to 5 min.
      // Client timeout must exceed that — use 330s (5.5 min) to give the proxy headroom
      // to return the final downloaded URL after the last poll.
      const timeoutMs = req.timeoutMs ?? 330_000;
      const resp = await fetch(`http://127.0.0.1:${port}/v1/videos/generations`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body,
        signal: AbortSignal.timeout(timeoutMs),
      });
      if (!resp.ok) {
        const errText = await resp.text().catch(() => "");
        throw new Error(`BlockRun video generation failed (${resp.status}): ${errText}`);
      }
      const result = (await resp.json()) as {
        data?: Array<{ url?: string; duration_seconds?: number }>;
        model?: string;
      };
      const videos = await Promise.all(
        (result.data ?? []).map(async (clip) => {
          // URL format: http://localhost:PORT/videos/FILENAME
          const filename = clip.url?.split("/videos/").pop();
          if (!filename) throw new Error(`Unexpected video URL format: ${clip.url}`);
          const filePath = join(VIDEO_DIR, filename);
          const buffer = await readFileAsync(filePath);
          const ext = filename.split(".").pop()?.toLowerCase() ?? "mp4";
          const mimeType =
            ext === "webm" ? "video/webm" : ext === "mov" ? "video/quicktime" : "video/mp4";
          return {
            buffer,
            mimeType,
            fileName: filename,
            metadata: {
              ...(clip.duration_seconds ? { duration_seconds: clip.duration_seconds } : {}),
            },
          };
        }),
      );
      return {
        videos,
        model: result.model ?? req.model,
      };
    },
  };
}

/**
 * Restart the proxy in-place after a chain switch.
 * Closes the running proxy (freeing port 8402) and starts a fresh one
 * that reads the newly persisted payment-chain preference from disk.
 * Fire-and-forget — the wallet command returns immediately with a status message.
 */
function restartProxyForChainSwitch(api: OpenClawPluginApi): void {
  const oldHandle = activeProxyHandle;
  activeProxyHandle = null;
  const restartGeneration = beginProxyStartupAttempt();
  const doRestart = async () => {
    if (oldHandle) {
      try {
        await oldHandle.close();
      } catch {
        // Ignore close errors — port may already be free
      }
    }
    // Brief pause so the OS releases the port before we re-bind
    await new Promise((r) => setTimeout(r, 300));
    if (!isProxyStartupCurrent(restartGeneration)) return;
    await startProxyInBackground(api, restartGeneration);
  };
  doRestart().catch((err) => {
    if (isProxyStartupCurrent(restartGeneration)) {
      resetProxyStartupState();
    }
    api.logger.error(
      `Failed to restart proxy after chain switch: ${err instanceof Error ? err.message : String(err)}`,
    );
  });
}

function createWalletCommand(api?: OpenClawPluginApi): OpenClawPluginCommandDefinition {
  return {
    name: "wallet",
    description: "Show BlockRun wallet info, balance, chain, or export key",
    acceptsArgs: true,
    requireAuth: true,
    handler: async (ctx: PluginCommandContext) => {
      const subcommand = ctx.args?.trim().toLowerCase() || "status";

      // API-key mode has no wallet, no chain and no key to export. Answer with
      // the account instead of resolving (and, for the chain subcommands,
      // silently GENERATING) wallet material this user will never spend from.
      const activeApiKey = (await resolveApiKey())?.key;
      if (activeApiKey) {
        return {
          text: [
            "**BlockRun account** (API key)",
            "",
            `**Key:** \`${maskApiKey(activeApiKey)}\``,
            "**Billing:** account credit — no wallet, no payment chain, no gas.",
            "",
            `**Add credit:** ${PORTAL_CREDITS_URL}`,
            `**Usage & keys:** ${PORTAL_KEYS_URL}`,
            "",
            "To pay with a USDC wallet over x402 instead, run `clawrouter logout` and restart.",
          ].join("\n"),
        };
      }

      let wallet: WalletResolution | undefined;
      try {
        wallet =
          subcommand === "status" || subcommand === "export"
            ? await resolveExistingWalletKey()
            : await resolveOrGenerateWalletKey();
      } catch (error) {
        return {
          text: `Could not load the BlockRun wallet: ${error instanceof Error ? error.message : String(error)}`,
          isError: true,
        };
      }
      if (!wallet) {
        return {
          text: "No BlockRun wallet found. Run `clawrouter setup` or connect an agent in ClawRouter Desktop to create one.",
          isError: true,
        };
      }
      const walletKey = wallet.key;
      const address = wallet.address;
      const resolvedSolanaKey = wallet.solanaPrivateKeyBytes;
      const walletPath = wallet.source === "core" ? CORE_WALLET_FILE : WALLET_FILE;

      if (subcommand === "export") {
        // Export private key + mnemonic for backup
        const lines = [
          "**ClawRouter Wallet Export**",
          "",
          "**SECURITY WARNING**: Your private key and mnemonic control your wallet funds.",
          "Never share these. Anyone with them can spend your USDC.",
          "",
          "**EVM (Base):**",
          `  Address: \`${address}\``,
          `  Private Key: \`${walletKey}\``,
        ];

        // Include mnemonic if it exists (Solana wallet derived from it)
        let hasMnemonic = false;
        try {
          if (existsSync(MNEMONIC_FILE)) {
            const mnemonic = readTextFileSync(MNEMONIC_FILE).trim();
            if (mnemonic) {
              hasMnemonic = true;
              // Derive Solana address for display
              const { deriveSolanaKeyBytes } = await import("./wallet.js");
              const solKeyBytes = deriveSolanaKeyBytes(mnemonic);
              const { createKeyPairSignerFromPrivateKeyBytes } = await import("@solana/kit");
              const signer = await createKeyPairSignerFromPrivateKeyBytes(solKeyBytes);

              lines.push(
                "",
                "**Solana:**",
                `  Address: \`${signer.address}\``,
                `  (Derived from mnemonic below)`,
                "",
                "**Mnemonic (24 words):**",
                `\`${mnemonic}\``,
                "",
                "CRITICAL: Back up this mnemonic. It is the ONLY way to recover your Solana wallet.",
              );
            }
          }
        } catch {
          // No mnemonic - EVM-only wallet
        }

        if (!hasMnemonic && resolvedSolanaKey) {
          try {
            const { createKeyPairSignerFromPrivateKeyBytes } = await import("@solana/kit");
            const signer = await createKeyPairSignerFromPrivateKeyBytes(resolvedSolanaKey);
            lines.push(
              "",
              "**Solana:**",
              `  Address: \`${signer.address}\``,
              wallet.source === "core"
                ? `  Private key managed by BlockRun Core: \`${CORE_SOLANA_WALLET_FILE}\``
                : "  Private key is managed by the configured wallet source.",
            );
          } catch {
            // Base export remains usable if Solana address derivation is unavailable.
          }
        }

        lines.push(
          "",
          "**To restore on a new machine:**",
          "1. Set the environment variable before running OpenClaw:",
          `   \`export BLOCKRUN_WALLET_KEY=${walletKey}\``,
          "2. Or save to file:",
          `   \`mkdir -p ~/.blockrun && echo "${walletKey}" > ~/.blockrun/.session && chmod 600 ~/.blockrun/.session\``,
        );

        if (hasMnemonic) {
          lines.push(
            "3. Restore the mnemonic for Solana:",
            `   \`echo "<your mnemonic>" > ~/.openclaw/blockrun/mnemonic && chmod 600 ~/.openclaw/blockrun/mnemonic\``,
          );
        }

        return { text: lines.join("\n") };
      }

      if (subcommand === "solana") {
        // Switch to Solana chain. If mnemonic already exists, just persist the selection.
        // If no mnemonic, set up Solana wallet first.
        try {
          let solanaAddr: string | undefined;

          if (resolvedSolanaKey) {
            await savePaymentChain("solana");
            const { createKeyPairSignerFromPrivateKeyBytes } = await import("@solana/kit");
            const signer = await createKeyPairSignerFromPrivateKeyBytes(resolvedSolanaKey);
            solanaAddr = signer.address;
            if (api) restartProxyForChainSwitch(api);
            return {
              text: [
                "✓ Payment chain switched to **Solana**.",
                api ? "Proxy restarting in background (~2s)." : "Restart the gateway to apply.",
                "",
                `**Solana Address:** \`${solanaAddr}\``,
                `**Fund with USDC on Solana:** https://solscan.io/account/${solanaAddr}`,
              ].join("\n"),
            };
          }

          // Check if Solana wallet is already set up (mnemonic exists)
          if (existsSync(MNEMONIC_FILE)) {
            const existingMnemonic = readTextFileSync(MNEMONIC_FILE).trim();
            if (existingMnemonic) {
              // Already set up — switch chain and restart proxy in-place
              await savePaymentChain("solana");
              const { deriveSolanaKeyBytes } = await import("./wallet.js");
              const solKeyBytes = deriveSolanaKeyBytes(existingMnemonic);
              const { createKeyPairSignerFromPrivateKeyBytes } = await import("@solana/kit");
              const signer = await createKeyPairSignerFromPrivateKeyBytes(solKeyBytes);
              solanaAddr = signer.address;
              if (api) restartProxyForChainSwitch(api);
              return {
                text: [
                  "✓ Payment chain switched to **Solana**.",
                  api ? "Proxy restarting in background (~2s)." : "Restart the gateway to apply.",
                  "",
                  `**Solana Address:** \`${solanaAddr}\``,
                  `**Fund with USDC on Solana:** https://solscan.io/account/${solanaAddr}`,
                ].join("\n"),
              };
            }
          }

          // No mnemonic — first-time Solana setup
          const { solanaPrivateKeyBytes } = await setupSolana();
          await savePaymentChain("solana");
          const { createKeyPairSignerFromPrivateKeyBytes } = await import("@solana/kit");
          const signer = await createKeyPairSignerFromPrivateKeyBytes(solanaPrivateKeyBytes);
          if (api) restartProxyForChainSwitch(api);
          return {
            text: [
              "**Solana Wallet Set Up**",
              "",
              `**Solana Address:** \`${signer.address}\``,
              `**Mnemonic File:** \`${MNEMONIC_FILE}\``,
              "",
              "Your existing EVM wallet is unchanged.",
              api
                ? "✓ Payment chain switched to Solana. Proxy restarting in background (~2s)."
                : "Payment chain set to Solana. Restart the gateway to apply.",
              "",
              `**Fund with USDC on Solana:** https://solscan.io/account/${signer.address}`,
            ].join("\n"),
          };
        } catch (err) {
          return {
            text: `Failed to set up Solana: ${err instanceof Error ? err.message : String(err)}`,
            isError: true,
          };
        }
      }

      if (subcommand === "arc") {
        // Switch to Circle's Arc. Same EVM key and address as Base — nothing to
        // set up, only the chain (and gateway) the USDC is paid on changes.
        try {
          await savePaymentChain("arc");
          if (api) restartProxyForChainSwitch(api);
          return {
            text: [
              api
                ? "✓ Payment chain switched to **Arc (EVM)**. Proxy restarting in background (~2s)."
                : "Payment chain set to Arc (EVM). Restart the gateway to apply.",
              "",
              `**Arc Address:** \`${address}\` (same as your Base address)`,
              "Fund with USDC on Arc to pay for calls.",
            ].join("\n"),
          };
        } catch (err) {
          return {
            text: `Failed to set payment chain: ${err instanceof Error ? err.message : String(err)}`,
            isError: true,
          };
        }
      }

      if (subcommand === "base") {
        // Switch back to Base (EVM) payment chain
        try {
          await savePaymentChain("base");
          if (api) restartProxyForChainSwitch(api);
          return {
            text: api
              ? "✓ Payment chain switched to **Base (EVM)**. Proxy restarting in background (~2s)."
              : "Payment chain set to Base (EVM). Restart the gateway to apply.",
          };
        } catch (err) {
          return {
            text: `Failed to set payment chain: ${err instanceof Error ? err.message : String(err)}`,
            isError: true,
          };
        }
      }

      // Default: show wallet status — run all checks in parallel for speed
      const evmBalancePromise = (async () => {
        try {
          const monitor = new BalanceMonitor(address!);
          const balance = await monitor.checkBalance();
          return `Balance: ${balance.balanceUSD}`;
        } catch {
          return "Balance: (could not check)";
        }
      })();

      const chainPromise = resolvePaymentChain();

      // Arc shares the EVM address; its USDC is only read when Arc is the
      // active chain, so a Base or Solana user's /wallet never calls the Arc gateway.
      const arcPromise = (async () => {
        if ((await chainPromise) !== "arc") return "";
        let arcBalanceText = "Balance: (could not check)";
        try {
          const balance = await new BalanceMonitor(address!, "arc").checkBalance();
          arcBalanceText = `Balance: ${balance.balanceUSD}`;
        } catch {
          // keep default
        }
        return ["", "**Arc (EVM):**", `  Address: \`${address}\``, `  ${arcBalanceText}`].join(
          "\n",
        );
      })();

      const solanaPromise = (async () => {
        try {
          if (!resolvedSolanaKey) return "";
          const { createKeyPairSignerFromPrivateKeyBytes } = await import("@solana/kit");
          const signer = await createKeyPairSignerFromPrivateKeyBytes(resolvedSolanaKey);
          const solAddr = signer.address;

          let solBalanceText = "Balance: (could not check)";
          try {
            const { SolanaBalanceMonitor } = await import("./solana-balance.js");
            const solMonitor = new SolanaBalanceMonitor(solAddr);
            const solBalance = await solMonitor.checkBalance();
            solBalanceText = `Balance: ${solBalance.balanceUSD}`;
          } catch {
            // keep default
          }

          return [
            "",
            "**Solana:**",
            `  Address: \`${solAddr}\``,
            `  ${solBalanceText}`,
            `  Fund (USDC only): https://solscan.io/account/${solAddr}`,
          ].join("\n");
        } catch {
          return "";
        }
      })();

      const usagePromise = (async () => {
        try {
          const stats = await getStats(7);
          if (stats.totalRequests === 0) return "";
          const modelLines = Object.entries(stats.byModel)
            .sort((a, b) => b[1].count - a[1].count)
            .slice(0, 8)
            .map(
              ([model, data]) =>
                `  ${model.length > 30 ? model.slice(0, 27) + "..." : model}  ${data.count} reqs  $${data.cost.toFixed(4)}`,
            );
          return [
            "",
            `**Usage (${stats.period}):**`,
            `  Total: ${stats.totalRequests} requests, $${stats.totalCost.toFixed(4)} spent`,
            stats.totalSavings > 0
              ? `  Saved: $${stats.totalSavings.toFixed(4)} (${stats.savingsPercentage.toFixed(0)}% vs Opus baseline)`
              : "",
            "",
            "**Top Models:**",
            ...modelLines,
          ]
            .filter(Boolean)
            .join("\n");
        } catch {
          return "";
        }
      })();

      const [evmBalanceText, solanaSection, currentChain, arcSection, usageSection] =
        await Promise.all([
          evmBalancePromise,
          solanaPromise,
          chainPromise,
          arcPromise,
          usagePromise,
        ]);

      return {
        text: [
          "**ClawRouter Wallet**",
          "",
          `**Payment Chain:** ${currentChain === "solana" ? "Solana" : `${PAYMENT_CHAIN_LABELS[currentChain]} (EVM)`}`,
          "",
          "**Base (EVM):**",
          `  Address: \`${address}\``,
          `  ${evmBalanceText}`,
          `  Fund (USDC only): https://basescan.org/address/${address}`,
          arcSection,
          solanaSection,
          usageSection,
          "",
          `**Key File:** \`${walletPath}\``,
          "",
          "**Commands:**",
          "• `/wallet` - Show this status",
          "• `/wallet export` - Export private key for backup",
          "• `/stats` - Detailed usage breakdown",
          !solanaSection ? "• `/wallet solana` - Enable Solana payments" : "",
          currentChain !== "base" ? "• `/wallet base` - Switch to Base (EVM)" : "",
          currentChain !== "arc" ? "• `/wallet arc` - Switch to Arc (EVM, same address)" : "",
          solanaSection && currentChain !== "solana" ? "• `/wallet solana` - Switch to Solana" : "",
        ]
          .filter(Boolean)
          .join("\n"),
      };
    },
  };
}

/**
 * This plugin's OpenClaw id. NOT "clawrouter" — OpenClaw bundles its own plugin
 * under that id since the 2026.7.1 line, and a duplicate loses to the bundled
 * one. Kept as one constant so the manifest, the plugin definition and the
 * config migration can never drift apart. See #305.
 */
export { BLOCKRUN_PLUGIN_ID } from "./openclaw-plugin-config.js";

const plugin: OpenClawPluginDefinition = {
  // NOT "clawrouter". OpenClaw bundles its own plugin under that id since the
  // 2026.7.1 line (vendored at dist/extensions/clawrouter, provider `clawrouter/*`,
  // CLAWROUTER_API_KEY, clawrouter.openclaw.ai). A duplicate id loses to the
  // bundled one — "global plugin will be overridden by bundled plugin" — so this
  // plugin silently never loaded and the local proxy never started. Different
  // product, different id. See #305.
  id: BLOCKRUN_PLUGIN_ID,
  name: "BlockRun ClawRouter",
  description: "Smart LLM router — 82 models, x402 micropayments, 84% cost savings",
  version: VERSION,

  register(api: OpenClawPluginApi) {
    // Check if ClawRouter is disabled via environment variable
    // Usage: CLAWROUTER_DISABLED=true openclaw gateway start
    const isDisabled =
      process["env"].CLAWROUTER_DISABLED === "true" || process["env"].CLAWROUTER_DISABLED === "1";
    if (isDisabled) {
      api.logger.info("ClawRouter disabled (CLAWROUTER_DISABLED=true). Using default routing.");
      return;
    }

    // Guard against repeated proxy startup within the same process.
    // OpenClaw calls register() multiple times (discovery, activation, per-session)
    // AND may load duplicate plugin instances from stale install-stage directories.
    // Provider/command/tool registration is idempotent — safe to repeat so the
    // LAST loaded plugin (the correct one) wins.  Only proxy startup must be guarded
    // to avoid EADDRINUSE.
    const proc = process as ProcessWithClawRouterState;
    const proxyAlreadyStarted = !!proc.__clawrouterProxyStarted;

    // Skip heavy initialization in completion mode — only completion script is needed
    // Logging to stdout during completion pollutes the script and causes zsh errors
    if (isCompletionMode()) {
      api.registerProvider(blockrunProvider);
      return;
    }

    // Register BlockRun as a provider (sync — available immediately)
    api.registerProvider(blockrunProvider);

    // Register native image and music generation providers so BlockRun models
    // appear in OpenClaw's /imagine and music generation UIs.
    api.registerImageGenerationProvider(buildImageGenerationProvider());
    api.registerMusicGenerationProvider(buildMusicGenerationProvider());
    if (typeof api.registerVideoGenerationProvider === "function") {
      api.registerVideoGenerationProvider(buildVideoGenerationProvider());
    } else {
      api.logger.warn(
        "OpenClaw runtime does not expose registerVideoGenerationProvider(); BlockRun video models unavailable on this version.",
      );
    }
    const webSearchDisabled = isBlockrunWebSearchDisabled(api.config as unknown);
    if (typeof api.registerWebSearchProvider === "function") {
      if (!webSearchDisabled) {
        api.registerWebSearchProvider(blockrunExaWebSearchProvider);
      }
    } else {
      api.logger.warn(
        "OpenClaw runtime does not expose registerWebSearchProvider(); blockrun-exa search is unavailable on this version.",
      );
    }

    // Inject models config into OpenClaw config file
    // This persists the config so models are recognized on restart
    injectModelsConfig(api.logger);

    // Repair OpenClaw's separate per-agent model cache, which openclaw.json's
    // two planes do not feed and which otherwise keeps serving retired models.
    syncAgentModelCache(api.logger);

    // Inject dummy auth profiles into agent auth stores
    // OpenClaw's agent system looks for auth even if provider has auth: []
    injectAuthProfile(api.logger);

    // Also set runtime config for immediate availability when the host allows
    // mutation. OpenClaw 2026.10.x freezes this object during registration.
    const runtimePort = getProxyPort();
    setRuntimeProviderConfig(api, runtimePort);
    // NOTE: tools.web.search.{provider,enabled} are NOT written to runtime
    // api.config here. OpenClaw 2026.5.4 appears to auto-inject the plugin's
    // registered provider id into config.tools.web.search.provider when it
    // sees runtime web_search config + registerWebSearchProvider() — and its
    // own writeConfigFile validator then rejects the auto-injected value.
    // We persist `enabled = true` only via injectModelsConfig (file write
    // path), which runs in gateway mode or under `clawrouter setup
    // --forceWrite`. The file write is gated to only set boolean `enabled`,
    // never the provider field, keeping the disk state validator-safe.
    const runtimeMcpRemoved = removeRuntimeMcpConfig(api);

    // Only log provider/tool registration on the first register() call.
    // OpenClaw calls register() 4+ times per gateway startup; logging every
    // time produces 24+ identical lines that obscure useful output.
    // Registration itself is idempotent (last wins), so always runs — just
    // the log is suppressed on repeat calls.
    const shouldLogRegistration = !proc.__clawrouterRegistrationLogged;
    proc.__clawrouterRegistrationLogged = true;

    if (shouldLogRegistration) {
      api.logger.info(
        `BlockRun provider registered (${VISIBLE_OPENCLAW_MODELS.length} models via x402)`,
      );
      if (typeof api.registerWebSearchProvider === "function") {
        if (webSearchDisabled) {
          api.logger.info(
            "BlockRun web search disabled (BLOCKRUN_WEB_SEARCH=off or tools.web.search.enabled=false)",
          );
        } else {
          api.logger.info(`Registered BlockRun web_search provider (${BLOCKRUN_EXA_PROVIDER_ID})`);
        }
      }
      if (runtimeMcpRemoved) {
        api.logger.info(
          `Removed bundled BlockRun MCP server config (${BLOCKRUN_MCP_SERVER_NAME}) — restart the gateway to free any leaked processes`,
        );
      }
    }

    // Register partner API tools (market data, predexon, image/video, ...)
    try {
      const proxyBaseUrl = `http://127.0.0.1:${runtimePort}`;
      const partnerTools = buildPartnerTools(proxyBaseUrl);
      for (const tool of partnerTools) {
        api.registerTool(tool);
      }
      // blockrun_polymarket is a LOCAL trading tool (signs CLOB orders with the
      // ClawRouter wallet key), not an HTTP-proxy partner tool — register it
      // separately so real-money betting works out of the box.
      // No deps: the tool's signing paths resolve the same process-wide ledger
      // themselves, at call time. Passing it here instead would construct the
      // SpendControl — and read spending.json off disk — on every plugin
      // registration, including for the many installs that never place a bet.
      api.registerTool(buildPolymarketTool());
      if (partnerTools.length > 0 && shouldLogRegistration) {
        api.logger.info(
          `Registered ${partnerTools.length} partner tool(s): ${partnerTools.map((t) => t.name).join(", ")}, blockrun_polymarket`,
        );
      }
    } catch (err) {
      api.logger.warn(
        `Failed to register partner tools: ${err instanceof Error ? err.message : String(err)}`,
      );
    }

    // Register commands
    api.registerCommand({
      name: "partners",
      description: "List available partner APIs and pricing",
      acceptsArgs: false,
      requireAuth: false,
      handler: async () => {
        if (PARTNER_SERVICES.length === 0) {
          return { text: "No partner APIs available." };
        }

        // Compact grouped view — one line per tool, grouped by category.
        const byCategory = new Map<string, typeof PARTNER_SERVICES>();
        for (const svc of PARTNER_SERVICES) {
          const bucket = byCategory.get(svc.category) ?? [];
          bucket.push(svc);
          byCategory.set(svc.category, bucket);
        }

        // Column width — keep tool names + pricing aligned across groups.
        const toolWidth = Math.max(...PARTNER_SERVICES.map((s) => `blockrun_${s.id}`.length), 28);
        const priceWidth = Math.max(
          ...PARTNER_SERVICES.map((s) =>
            s.pricing.perUnit === "free" ? 4 : `${s.pricing.perUnit}/${s.pricing.unit}`.length,
          ),
          12,
        );

        const lines = ["**Partner APIs** (paid via your ClawRouter wallet)", ""];
        for (const [category, services] of byCategory) {
          lines.push(`**${category}**`);
          for (const svc of services) {
            const tool = `blockrun_${svc.id}`.padEnd(toolWidth);
            const price = (
              svc.pricing.perUnit === "free" ? "free" : `${svc.pricing.perUnit}/${svc.pricing.unit}`
            ).padEnd(priceWidth);
            lines.push(`  \`${tool}\` ${price}  ${svc.shortDescription}`);
          }
          lines.push("");
        }
        lines.push("Tool-call any of these in chat, or use `/cr-imagegen` / `/videogen` directly.");

        return { text: lines.join("\n") };
      },
    });

    // /cr-imagegen <prompt> [--model=alias] [--size=1024x1024] [--n=1]
    // Renamed from /imagegen — Telegram channels reserve /imagegen for their own
    // image-gen bots, and OpenClaw's runtime emits a collision warning when both
    // claim the same prefix. The `/imagegen` chat-prefix path in proxy.ts still
    // works for backward compatibility.
    api.registerCommand({
      name: "cr-imagegen",
      description: "Generate an image (BlockRun image models, paid via wallet)",
      acceptsArgs: true,
      // Paid from the wallet: only authorized senders.
      requireAuth: true,
      handler: async (ctx: PluginCommandContext) => {
        const parsed = parseGenArgs(ctx.args ?? "");
        if (!parsed.prompt) {
          return {
            text: "Usage: `/cr-imagegen <prompt> [--model=<alias>] [--size=1024x1024] [--n=1]`\n\nAliases: `nano-banana` (default), `banana-2` (Gemini 3.1 Flash quality), `banana-pro`, `dalle`, `gpt-image`, `flux`, `grok-imagine`, `grok-imagine-pro`, `cogview`.",
          };
        }
        const model = resolveModelAlias(parsed.model ?? "nano-banana");
        const port = getProxyPort();
        try {
          const resp = await fetch(`http://127.0.0.1:${port}/v1/images/generations`, {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({
              model,
              prompt: parsed.prompt,
              size: parsed.size ?? "1024x1024",
              n: parsed.n ?? 1,
            }),
            signal: AbortSignal.timeout(180_000),
          });
          if (!resp.ok) {
            const errText = await resp.text().catch(() => "");
            if (resp.status === 402) {
              return {
                text: `Insufficient wallet balance for image generation. Top up with \`/wallet\`.\n\n${errText}`,
              };
            }
            return { text: `Image generation failed (${resp.status}): ${errText}` };
          }
          const result = (await resp.json()) as {
            data?: Array<{ url?: string; revised_prompt?: string }>;
          };
          const urls = (result.data ?? []).map((d) => d.url).filter(Boolean) as string[];
          if (urls.length === 0) {
            return { text: "Image generation returned no results." };
          }
          return {
            text: urls.map((u, i) => `![image ${i + 1}](${u})`).join("\n\n"),
          };
        } catch (err) {
          return {
            text: `Image generation error: ${err instanceof Error ? err.message : String(err)}`,
          };
        }
      },
    });

    // /videogen <prompt> [--model=alias] [--duration=5|8|10]
    api.registerCommand({
      name: "videogen",
      description: "Generate a short video (Grok Imagine / Seedance, paid via wallet)",
      acceptsArgs: true,
      // Paid from the wallet: only authorized senders.
      requireAuth: true,
      handler: async (ctx: PluginCommandContext) => {
        const parsed = parseGenArgs(ctx.args ?? "");
        if (!parsed.prompt) {
          return {
            text: "Usage: `/videogen <prompt> [--model=<alias>] [--duration=5|8|10]`\n\nAliases: `seedance` (1.5-pro, default — cheapest), `seedance-2-fast`, `seedance-2`, `seedance-2-mini` (720p + audio, half the flagship rate), `seedance-2.5` (720p + synced audio, long-form), `grok-video`, `grok-video-1.5` (synced audio).\n\n⏱️  Generation takes 60–180 seconds. Payment settles only on success.",
          };
        }
        const model = resolveModelAlias(parsed.model ?? "seedance");
        const port = getProxyPort();
        try {
          const resp = await fetch(`http://127.0.0.1:${port}/v1/videos/generations`, {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({
              model,
              prompt: parsed.prompt,
              ...(parsed.duration ? { duration_seconds: parsed.duration } : {}),
            }),
            signal: AbortSignal.timeout(330_000),
          });
          if (!resp.ok) {
            const errText = await resp.text().catch(() => "");
            if (resp.status === 402) {
              return {
                text: `Insufficient wallet balance for video generation. Top up with \`/wallet\`.\n\n${errText}`,
              };
            }
            return { text: `Video generation failed (${resp.status}): ${errText}` };
          }
          const result = (await resp.json()) as {
            data?: Array<{ url?: string }>;
          };
          const urls = (result.data ?? []).map((d) => d.url).filter(Boolean) as string[];
          if (urls.length === 0) {
            return { text: "Video generation returned no results." };
          }
          return { text: urls.map((u, i) => `Video ${i + 1}: ${u}`).join("\n") };
        } catch (err) {
          return {
            text: `Video generation error: ${err instanceof Error ? err.message : String(err)}`,
          };
        }
      },
    });

    // /cr-call <+E.164> "<task>" [--voice nat] [--max-duration 5] [--from +1...] [--language en-US]
    // Places a REAL outbound AI voice call via BlockRun → Bland.ai. Returns
    // immediately with call_id + poll_url; the call itself runs in the cloud
    // for up to 30 min. Use `clawrouter phone numbers list` to see wallet-owned
    // numbers usable as `--from`. The `cr-` prefix avoids the Telegram-channel
    // collision pattern that bit `/imagegen` in v0.12.190 — `/call` and
    // `/phone` are even more commonly reserved by chat platforms than
    // `/imagegen` was, so we don't register either bare form here.
    api.registerCommand({
      name: "cr-call",
      description: "Place an AI voice call via BlockRun + Bland.ai (paid from wallet, $0.54/call)",
      acceptsArgs: true,
      // Paid from the wallet: only authorized senders.
      requireAuth: true,
      handler: async (ctx: PluginCommandContext) => {
        const parsed = parseCallArgs(ctx.args ?? "");
        if (!parsed.to || !parsed.task) {
          return {
            text:
              'Usage: `/cr-call +1<E.164-number> "<what the AI should say>" [--voice nat] [--max-duration 5] [--from +1<owned-number>] [--language en-US]`\n\n' +
              "Voices: `nat` (default), `josh`, `maya`, `june`, `paige`, `derek`, `florian`.\n\n" +
              "⚠️ Places a REAL phone call. $0.54 per call (covers up to 30 minutes). " +
              "Use `clawrouter phone numbers list` to see wallet-owned numbers usable as `--from`.",
          };
        }
        const port = getProxyPort();
        try {
          const resp = await fetch(`http://127.0.0.1:${port}/v1/voice/call`, {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({
              to: parsed.to,
              task: parsed.task,
              ...(parsed.voice ? { voice: parsed.voice } : {}),
              ...(parsed.from ? { from: parsed.from } : {}),
              ...(parsed.language ? { language: parsed.language } : {}),
              ...(parsed.max_duration !== undefined ? { max_duration: parsed.max_duration } : {}),
            }),
            signal: AbortSignal.timeout(60_000),
          });
          if (!resp.ok) {
            const errText = await resp.text().catch(() => "");
            if (resp.status === 402) {
              return {
                text: `Insufficient wallet balance for voice call ($0.54). Top up with \`/wallet\`.\n\n${errText}`,
              };
            }
            return { text: `Voice call failed (${resp.status}): ${errText}` };
          }
          const result = (await resp.json()) as {
            call_id?: string;
            poll_url?: string;
            status?: string;
          };
          if (!result.call_id) {
            return {
              text: `Voice call accepted but no call_id returned: ${JSON.stringify(result)}`,
            };
          }
          const lines = [
            `📞 Calling **${parsed.to}** (call_id: \`${result.call_id}\`)`,
            "",
            `Status: ${result.status ?? "queued"}`,
          ];
          if (result.poll_url) {
            lines.push(`Poll: \`GET ${result.poll_url}\``);
          } else {
            lines.push(`Poll: \`GET http://localhost:${port}/v1/voice/call/${result.call_id}\``);
          }
          lines.push(
            "",
            "Call runs in the cloud for up to 30 min. Transcript + recording appear once status is `completed`.",
          );
          return { text: lines.join("\n") };
        } catch (err) {
          return {
            text: `Voice call error: ${err instanceof Error ? err.message : String(err)}`,
          };
        }
      },
    });

    // Register commands synchronously so OpenClaw sees them during the register() call.
    // These factories are plain functions (no top-level await) — marking them async
    // caused .then() callbacks to fire after register() returned, making OpenClaw miss them.
    // Primary: /wallet (original name, lobster.cash removed by update script)
    api.registerCommand(createWalletCommand(api));
    // Alias: /blockrun (guaranteed unique fallback)
    try {
      const blockrunAlias = createWalletCommand(api);
      blockrunAlias.name = "blockrun";
      api.registerCommand(blockrunAlias);
    } catch {
      // Silently ignored if "blockrun" is already claimed
    }
    api.registerCommand(createStatsCommand());
    api.registerCommand(createExcludeCommand());
    api.registerCommand(
      createPolicyCommand({
        liveControl: () =>
          (process as ProcessWithClawRouterState).__clawrouterProxyStarted
            ? getSharedSpendControl()
            : undefined,
      }),
    );
    if (shouldLogRegistration) {
      api.logger.info(
        "Commands registered: /wallet, /blockrun, /stats, /exclude, /policy, /partners, /cr-imagegen, /videogen, /cr-call",
      );
    }

    // Register a service with stop() for cleanup on gateway shutdown
    // This prevents EADDRINUSE when the gateway restarts
    api.registerService({
      id: "clawrouter-proxy",
      start: () => {
        // No-op: proxy is started below in non-blocking mode
      },
      stop: async () => {
        // Close proxy on gateway shutdown to release port 8402
        if (activeProxyHandle) {
          try {
            await activeProxyHandle.close();
            api.logger.info("BlockRun proxy closed");
          } catch (err) {
            api.logger.warn(
              `Failed to close proxy: ${err instanceof Error ? err.message : String(err)}`,
            );
          }
          activeProxyHandle = null;
        }
        resetProxyStartupState();
      },
    });

    // Skip proxy startup unless we're in gateway mode
    // The proxy keeps the Node.js event loop alive, preventing CLI commands from exiting
    // The proxy will start automatically when the gateway runs
    if (!isGatewayMode()) {
      if (shouldLogRegistration) {
        // Generate wallet on first install (even outside gateway mode)
        // This ensures users can see their wallet address immediately after install
        //
        // ...unless the user pays by card. resolveOrGenerateWalletKey() MINTS a
        // key as a side effect, so running it unconditionally handed an API-key
        // customer a private key they never asked for plus a "back this up or
        // lose your USDC" warning they cannot act on — and broke the documented
        // promise that API-key mode never generates, reads or signs with one.
        // The gateway-mode path (startProxyInBackground) has always resolved the
        // key before touching a wallet; this path had not.
        void (async () => {
          // resolveApiKey() THROWS when a key is present but malformed, and
          // that refusal is the point: falling through would resolve the next
          // credential instead, which can be a different account or a funded
          // wallet. Catching it here would silently undo exactly that
          // protection, so a malformed key stops this path rather than
          // downgrading to "generate a wallet and spend USDC". Reported and
          // returned, not rethrown — an unhandled rejection inside plugin
          // registration takes OpenClaw down with it, and the user needs to
          // read the reason.
          let keyResolution: Awaited<ReturnType<typeof resolveApiKey>>;
          try {
            keyResolution = await resolveApiKey();
          } catch (error) {
            api.logger.error(
              `BlockRun API key is configured but unusable: ${error instanceof Error ? error.message : String(error)}`,
            );
            api.logger.error(
              `Not falling back to a wallet — fix the key, or run "clawrouter logout" to pay from the wallet deliberately.`,
            );
            return;
          }
          if (keyResolution) {
            api.logger.info(
              `Using BlockRun API key ${maskApiKey(keyResolution.key)} (from ${keyResolution.source}) — billing account credit, no wallet`,
            );
            return;
          }
          const { address, source } = await resolveOrGenerateWalletKey();
          if (source === "generated") {
            api.logger.warn(`════════════════════════════════════════════════`);
            api.logger.warn(`  NEW WALLET GENERATED — BACK UP YOUR KEY NOW!`);
            api.logger.warn(`  Address : ${address}`);
            api.logger.warn(`  Run /wallet export to get your private key`);
            api.logger.warn(`  Losing this key = losing your USDC funds`);
            api.logger.warn(`════════════════════════════════════════════════`);
          } else if (source === "core") {
            api.logger.info(`Using BlockRun Core wallet: ${address}`);
          } else if (source === "saved") {
            api.logger.info(`Using saved wallet: ${address}`);
          } else if (source === "config") {
            api.logger.info(`Using wallet from plugin config: ${address}`);
          } else {
            api.logger.info(`Using wallet from BLOCKRUN_WALLET_KEY: ${address}`);
          }
        })().catch((err) => {
          api.logger.warn(
            `Failed to initialize wallet: ${err instanceof Error ? err.message : String(err)}`,
          );
        });
        api.logger.info("Not in gateway mode — proxy will start when gateway runs");
      }
      return;
    }

    // Start x402 proxy in background WITHOUT blocking register()
    // CRITICAL: Do NOT await here - this was blocking model selection UI for 3+ seconds
    // causing Chandler's "infinite loop" issue where model selection never finishes
    // Note: startProxyInBackground calls resolveOrGenerateWalletKey internally
    //
    // Guard: only start proxy once per process. When OpenClaw loads duplicate plugin
    // instances (stale install-stage dirs), each calls register() — provider/command
    // registration above is idempotent, but proxy startup must happen exactly once.
    //
    // Defer startup to handle multi-phase register() (#147): OpenClaw calls
    // register() twice during gateway startup. The first call happens before
    // openclaw.json has been parsed, so api.pluginConfig is empty. If we start
    // the proxy synchronously on that first call, the second call (which has
    // the user's routing config) gets blocked by the proxyAlreadyStarted guard
    // and the user's custom routing/wallet config is silently ignored.
    //
    // Strategy: when pluginConfig is empty, mark this register() call as a
    // pending "deferred start". A short timer schedules the actual startup.
    // If a second register() call arrives BEFORE the timer fires (the normal
    // case — OpenClaw calls them back-to-back), it cancels the deferred start
    // and starts the proxy immediately with the now-populated pluginConfig.
    // If only ever one call happens (rare — user with no plugin config and
    // single-phase gateway), the timer fires and starts the proxy with empty
    // config (defaults) so we don't deadlock.
    const pluginConfigEmpty =
      !api.pluginConfig ||
      typeof api.pluginConfig !== "object" ||
      Object.keys(api.pluginConfig).length === 0;

    // If we have a pending deferred start from a prior call, cancel it — this
    // call (with potentially populated pluginConfig) takes over.
    if (clearDeferredProxyStartTimer(proc)) {
      api.logger.info("Superseding earlier deferred proxy start — using current pluginConfig");
    }

    if (proxyAlreadyStarted) {
      if (!pluginConfigEmpty && proc.__clawrouterStartedWithEmptyConfig) {
        api.logger.info(
          "Populated pluginConfig arrived after provisional default startup — switching proxy to current config",
        );
        supersedeEmptyConfigStartup(api);
      } else if (shouldLogRegistration) {
        api.logger.info("Proxy already started by earlier register() call — skipping");
      }
      return;
    }

    if (pluginConfigEmpty) {
      // Defer 250ms so OpenClaw's second register() call (with populated
      // pluginConfig) has a chance to supersede this one.
      if (shouldLogRegistration) {
        api.logger.info(
          "pluginConfig empty — deferring proxy startup 250ms in case a populated config arrives",
        );
      }
      proc.__clawrouterDeferredStartTimer = setTimeout(() => {
        proc.__clawrouterDeferredStartTimer = undefined;
        if (proc.__clawrouterProxyStarted) return;
        const startupGeneration = beginProxyStartupAttempt(proc, true);
        api.logger.info("Deferred timer fired — starting proxy with default config");
        startProxyAfterPortProbe(api, startupGeneration);
      }, 250);
      return;
    }

    if (pendingConfiguredStartupApi) {
      pendingConfiguredStartupApi = null;
      api.logger.info("Discarding older queued populated pluginConfig — using newest config");
    }

    const startupGeneration = beginProxyStartupAttempt(proc, false);
    startProxyAfterPortProbe(api, startupGeneration);
  },

  /**
   * Cleanup hook called when plugin is uninstalled via `openclaw plugins uninstall`.
   * Removes blockrun provider config, plugin entries, model allowlist entries,
   * and auth profiles from openclaw.json so no residual config causes errors.
   */
  deactivate(api: OpenClawPluginApi) {
    // 1. Stop proxy
    if (activeProxyHandle) {
      activeProxyHandle.close().catch(() => {});
      activeProxyHandle = null;
    }
    resetProxyStartupState();

    // 2. Clean openclaw.json — remove provider, plugin entries, model allowlist
    try {
      const configPath = join(homedir(), ".openclaw", "openclaw.json");
      if (existsSync(configPath)) {
        const config = JSON.parse(readTextFileSync(configPath));

        // Remove blockrun provider
        if (config.models?.providers?.blockrun) {
          delete config.models.providers.blockrun;
        }

        // Remove managed BlockRun MCP server config, but preserve any user-managed override.
        removeManagedBlockrunMcpServerConfig(config as OpenClawConfig);

        // Remove plugin entries (all case variants)
        for (const key of [BLOCKRUN_PLUGIN_ID, "ClawRouter", "@blockrun/clawrouter"]) {
          if (config.plugins?.entries?.[key]) delete config.plugins.entries[key];
          if (config.plugins?.installs?.[key]) delete config.plugins.installs[key];
        }

        // Remove from plugins.allow
        if (Array.isArray(config.plugins?.allow)) {
          config.plugins.allow = config.plugins.allow.filter(
            (p: string) =>
              p !== BLOCKRUN_PLUGIN_ID && p !== "ClawRouter" && p !== "@blockrun/clawrouter",
          );
        }

        // A previous uninstall/disable may have left the managed id denied.
        // Remove only BlockRun-owned aliases; the official `clawrouter` id is
        // intentionally preserved.
        if (Array.isArray(config.plugins?.deny)) {
          config.plugins.deny = config.plugins.deny.filter(
            (p: string) =>
              p !== BLOCKRUN_PLUGIN_ID && p !== "ClawRouter" && p !== "@blockrun/clawrouter",
          );
        }

        // Remove blockrun models from allowlist
        if (config.agents?.defaults?.models) {
          for (const key of Object.keys(config.agents.defaults.models)) {
            if (key.startsWith("blockrun/")) delete config.agents.defaults.models[key];
          }
        }
        if (config.agents?.defaults) removeBlockrunModelPolicyAllow(config.agents.defaults);

        // Reset default model if it's blockrun
        if (config.agents?.defaults?.model?.primary?.startsWith("blockrun/")) {
          delete config.agents.defaults.model.primary;
        }

        if (config.tools?.web?.search?.provider === BLOCKRUN_EXA_PROVIDER_ID) {
          delete config.tools.web.search.provider;
        }

        // Atomic write
        const tmpPath = `${configPath}.tmp.${process.pid}`;
        writeFileSync(tmpPath, JSON.stringify(config, null, 2), { mode: 0o600 });
        renameSync(tmpPath, configPath);
        chmodSync(configPath, 0o600);
        api.logger.info("ClawRouter config cleaned up");
      }
    } catch (err) {
      api.logger.warn(`Config cleanup failed: ${err instanceof Error ? err.message : String(err)}`);
    }

    // 3. Clean auth profiles
    try {
      const agentsDir = join(homedir(), ".openclaw", "agents");
      if (existsSync(agentsDir)) {
        for (const entry of readdirSync(agentsDir, { withFileTypes: true })) {
          if (!entry.isDirectory()) continue;
          const authPath = join(agentsDir, entry.name, "agent", "auth-profiles.json");
          if (!existsSync(authPath)) continue;
          try {
            const store = JSON.parse(readTextFileSync(authPath));
            if (store.profiles?.["blockrun:default"]) {
              delete store.profiles["blockrun:default"];
              writePrivateJsonSync(authPath, store);
            }
          } catch {
            // Skip corrupt auth files
          }
        }
      }
    } catch {
      // Best-effort cleanup
    }

    api.logger.info("ClawRouter deactivated — restart gateway to complete uninstall");
  },
};

